def test_full_oracle(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    S = [set() for _ in range(n)]
    T = [set() for _ in range(m)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                S[i].add(j)
                T[j].add(i)
    row_ok = True
    for i in range(n):
        for j in range(i+1, n):
            if S[i] & S[j]:
                if S[i] != S[j]:
                    row_ok = False
                    break
        if not row_ok:
            break
    col_ok = True
    if row_ok:
        for i in range(m):
            for j in range(i+1, m):
                if T[i] & T[j]:
                    if T[i] != T[j]:
                        col_ok = False
                        break
            if not col_ok:
                break
    correct = row_ok and col_ok
    output = run(x).strip().lower()
    assert (output == 'yes') == correct

def test_row_necessary(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'yes':
        S = [set() for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    S[i].add(j)
        for i in range(n):
            for j in range(i+1, n):
                if S[i] & S[j]:
                    if S[i] != S[j]:
                        assert False

def test_column_necessary(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'yes':
        T = [set() for _ in range(m)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    T[j].add(i)
        for i in range(m):
            for j in range(i+1, m):
                if T[i] & T[j]:
                    if T[i] != T[j]:
                        assert False

def test_single_rowcol(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    output = run(x).strip().lower()
    if n == 1 or m == 1:
        assert output == 'yes'

def test_no_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    black_count = sum(row.count('#') for row in grid)
    if black_count == 0:
        assert output == 'yes'

def test_one_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    black_count = sum(row.count('#') for row in grid)
    if black_count == 1:
        assert output == 'yes'

def test_all_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    total_cells = n * m
    black_count = sum(row.count('#') for row in grid)
    if black_count == total_cells:
        assert output == 'yes'

def test_examples(run, x):
    examples = {
        "5 8\n.#.#..#.\n.....#..\n.#.#..#.\n#.#....#\n.....#..\n": "Yes",
        "5 5\n..#..\n..#..\n#####\n..#..\n..#..\n": "No",
        "5 9\n........#\n#........\n..##.#...\n.......#.\n....#.#.#\n": "No"
    }
    if x in examples:
        expected = examples[x].lower()
        output = run(x).strip().lower()
        assert output == expected

def test_output_format(run, x):
    output = run(x).strip()
    assert output
    lower = output.lower()
    assert lower in ("yes", "no")

def test_no_necessary(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'no':
        S = [set() for _ in range(n)]
        T = [set() for _ in range(m)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    S[i].add(j)
                    T[j].add(i)
        row_ok = True
        for i in range(n):
            for j in range(i+1, n):
                if S[i] & S[j]:
                    if S[i] != S[j]:
                        row_ok = False
                        break
            if not row_ok:
                break
        col_ok = True
        if row_ok:
            for i in range(m):
                for j in range(i+1, m):
                    if T[i] & T[j]:
                        if T[i] != T[j]:
                            col_ok = False
                            break
                if not col_ok:
                    break
        if row_ok and col_ok:
            assert False

