def test_small_bruteforce(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n > 4 or m > 4:
        return
    grid = lines[1:1+n]
    def solve_brute(grid):
        n = len(grid)
        m = len(grid[0])
        if all(grid[i][j] == '.' for i in range(n) for j in range(m)):
            return True
        max_groups = min(n, m)
        for g in range(1, max_groups+1):
            from itertools import product
            row_assignments = product(range(-1, g), repeat=n)
            col_assignments = product(range(-1, g), repeat=m)
            for row_groups in row_assignments:
                ok = True
                for i in range(n):
                    if row_groups[i] == -1:
                        if any(grid[i][j] == '#' for j in range(m)):
                            ok = False
                            break
                if not ok:
                    continue
                for col_groups in col_assignments:
                    ok = True
                    for j in range(m):
                        if col_groups[j] == -1:
                            if any(grid[i][j] == '#' for i in range(n)):
                                ok = False
                                break
                    if not ok:
                        continue
                    groups_rows = [[] for _ in range(g)]
                    groups_cols = [[] for _ in range(g)]
                    for i in range(n):
                        if row_groups[i] != -1:
                            groups_rows[row_groups[i]].append(i)
                    for j in range(m):
                        if col_groups[j] != -1:
                            groups_cols[col_groups[j]].append(j)
                    if any(len(groups_rows[k])==0 or len(groups_cols[k])==0 for k in range(g)):
                        continue
                    for k in range(g):
                        for i in groups_rows[k]:
                            for j in groups_cols[k]:
                                if grid[i][j] != '#':
                                    ok = False
                                    break
                            if not ok:
                                break
                        if not ok:
                            break
                    if not ok:
                        continue
                    for i in range(n):
                        for j in range(m):
                            if grid[i][j] == '#':
                                if row_groups[i] == -1 or col_groups[j] == -1 or row_groups[i] != col_groups[j]:
                                    ok = False
                                    break
                        if not ok:
                            break
                    if ok:
                        return True
        return False
    expected = solve_brute(grid)
    if expected:
        assert out == "yes", f"Brute-force says Yes but output is {out}"
    else:
        assert out == "no", f"Brute-force says No but output is {out}"

