    color[0] = 0
    stack = [0]
    cnt0 = 0
    cnt1 = 0
    while stack:
        u = stack.pop()
        if color[u] == 0:
            cnt0 += 1
        else:
            cnt1 += 1
        for v in adj[u]:
            if color[v] == -1:
                color[v] = color[u] ^ 1
