def test_exact(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n < 3 or n > 100:
        return
    a = list(map(int, lines[1].strip().split()))
    if len(a) != n:
        return
    for i in range(n):
        if a[i] < 1 or a[i] > 1000:
            return
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return
    best = 10**9
    for i in range(1, n-1):
        new_seq = a[:i] + a[i+1:]
        diff = max(new_seq[j+1] - new_seq[j] for j in range(len(new_seq)-1))
        best = min(best, diff)
    expected = best
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == expected

