def test_correctness_expansion(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    indices = list(range(n))
    indices.sort(key=lambda i: a[i], reverse=True)
    l = r = indices[0]
    ok = True
    for i in indices[1:]:
        if i == l - 1:
            l = i
        elif i == r + 1:
            r = i
        else:
            ok = False
            break
    correct = "YES" if ok else "NO"
    output = run(x).strip().upper()
    assert output == correct

def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n > 6:
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    from collections import deque
    initial = tuple((a[i],) for i in range(n))
    if any(len(p) == n for p in initial):
        correct = "YES"
    else:
        visited = {initial}
        q = deque([initial])
        found = False
        while q:
            state = q.popleft()
            for i in range(n):
                if len(state[i]) != 1:
                    continue
                disk = state[i][0]
                for j in (i-1, i+1):
                    if 0 <= j < n:
                        if len(state[j]) == 0 or disk < state[j][-1]:
                            new_state = list(state)
                            new_state[i] = ()
                            new_state[j] = state[j] + (disk,)
                            new_state = tuple(new_state)
                            if new_state not in visited:
                                if any(len(p) == n for p in new_state):
                                    found = True
                                    break
                                visited.add(new_state)
                                q.append(new_state)
                if found:
                    break
            if found:
                break
        correct = "YES" if found else "NO"
    output = run(x).strip().upper()
    assert output == correct

