def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n'), "Output must end with newline"
    line = out.strip()
    assert line.upper() in ("YES", "NO"), "Output must be YES or NO"

def test_example1(run, x):
    if x == "4\n1 3 4 2\n":
        out = run(x)
        assert out.strip().upper() == "YES", "Example 1 should output YES"

def test_example2(run, x):
    if x == "3\n3 1 2\n":
        out = run(x)
        assert out.strip().upper() == "NO", "Example 2 should output NO"

def test_monotonic(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    inc = all(a[i] < a[i+1] for i in range(n-1))
    dec = all(a[i] > a[i+1] for i in range(n-1))
    if inc or dec:
        out = run(x)
        assert out.strip().upper() == "YES", "Monotonic permutation must be YES"

def test_n3_all(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 3:
        return
    a = list(map(int, lines[1].split()))
    yes_perms = [
        [1,2,3],
        [1,3,2],
        [3,2,1]
    ]
    correct = a in yes_perms
    out = run(x)
    ans = out.strip().upper() == "YES"
    assert ans == correct, f"For n=3 permutation {a}, expected {'YES' if correct else 'NO'}"

def test_bruteforce_n6(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:
        return
    a = list(map(int, lines[1].split()))
    from collections import deque
    initial = tuple((r,) for r in a)
    def is_goal(state):
        full = [i for i, stack in enumerate(state) if len(stack) == n]
        if len(full) != 1:
            return False
        i_full = full[0]
        for i, stack in enumerate(state):
            if i != i_full and len(stack) > 0:
                return False
        return True
    if is_goal(initial):
        correct = True
    else:
        visited = {initial}
        q = deque([initial])
        found = False
        while q and not found:
            state = q.popleft()
            for i in range(n):
                if len(state[i]) == 1:
                    disk = state[i][0]
                    for j in (i-1, i+1):
                        if 0 <= j < n:
                            if len(state[j]) == 0 or state[j][-1] > disk:
                                new_stacks = list(state)
                                new_stacks[i] = ()
                                new_stacks[j] = state[j] + (disk,)
                                new_state = tuple(new_stacks)
                                if is_goal(new_state):
                                    found = True
                                    break
                                if new_state not in visited:
                                    visited.add(new_state)
                                    q.append(new_state)
                    if found:
                        break
        correct = found
    out = run(x)
    ans = out.strip().upper() == "YES"
    assert ans == correct, f"Brute force says {'YES' if correct else 'NO'}"

def test_contiguity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    pos = [0]*(n+1)
    for i, r in enumerate(a):
        pos[r] = i
    min_idx = max_idx = pos[n]
    possible = True
    for r in range(n-1, 0, -1):
        i = pos[r]
        if i < min_idx:
            min_idx = i
        elif i > max_idx:
            max_idx = i
        if max_idx - min_idx + 1 != n - r + 1:
            possible = False
            break
    out = run(x)
    ans = out.strip().upper() == "YES"
    assert ans == possible, f"Contiguity condition says {'YES' if possible else 'NO'}"

def test_symmetry(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    rev_a = list(reversed(a))
    pos = [0]*(n+1)
    for i, r in enumerate(rev_a):
        pos[r] = i
    min_idx = max_idx = pos[n]
    possible_rev = True
    for r in range(n-1, 0, -1):
        i = pos[r]
        if i < min_idx:
            min_idx = i
        elif i > max_idx:
            max_idx = i
        if max_idx - min_idx + 1 != n - r + 1:
            possible_rev = False
            break
    out = run(x)
    ans = out.strip().upper() == "YES"
    assert ans == possible_rev, f"Symmetry: reversed gives {'YES' if possible_rev else 'NO'}"

