def test_exact_match(run, x):
    def simulate(x):
        lines = x.strip().split('\n')
        n, q = map(int, lines[0].split())
        tasks = []
        for i in range(1, q + 1):
            t, k, d = map(int, lines[i].split())
            tasks.append((t, k, d))
        busy = [0] * n
        out = []
        for t, k, d in tasks:
            free = []
            for i in range(n):
                if busy[i] < t:
                    free.append(i)
                    if len(free) == k:
                        break
            if len(free) < k:
                out.append('-1')
            else:
                total = sum(i + 1 for i in free)
                for i in free:
                    busy[i] = t + d - 1
                out.append(str(total))
        return '\n'.join(out)
    expected = simulate(x).strip()
    actual = run(x).strip()
    assert actual == expected

def test_line_count(run, x):
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    out = run(x)
    if out == '':
        out_lines = []
    else:
        out_lines = out.rstrip('\n').split('\n')
    assert len(out_lines) == q

def test_integer_parsing(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        int(line)

def test_no_negative_except_minus_one(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        val = int(line)
        assert val == -1 or val > 0

def test_sum_bounds(run, x):
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    tasks = []
    for i in range(1, q + 1):
        t, k, d = map(int, lines[i].split())
        tasks.append((t, k, d))
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for (t, k, d), line in zip(tasks, out_lines):
        if line == '-1':
            continue
        s = int(line)
        min_sum = k * (k + 1) // 2
        max_sum = k * (2 * n - k + 1) // 2
        assert min_sum <= s <= max_sum

def test_n1_case(run, x):
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    if n == 1:
        out = run(x)
        out_lines = out.rstrip('\n').split('\n')
        for line in out_lines:
            assert line == '-1' or line == '1'

