        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    from collections import Counter
    out_pairs = []
    for i in range(n):
        prev = nums[i-1] if i>0 else 0
        nxt = nums[i+1] if i+1<n else 0
        out_pairs.append((prev, nxt))
    if Counter(out_pairs) != Counter(pairs):
