    grid = [list(map(int, line.split())) for line in out_lines]
    for i in range(n):
        for j in range(m):
            color = 0
            for op in reversed(ops):
                t, idx, c = op
                if t == 1 and idx == i+1:
                    color = c
                    break
                if t == 2 and idx == j+1:
                    color = c
                    break
            assert grid[i][j] == color"
