def test_brute_force_sim(run, x):
    lines = x.strip().splitlines()
    n, m, k = map(int, lines[0].split())
    ops = []
    for i in range(1, k+1):
        parts = lines[i].split()
        t = int(parts[0])
        idx = int(parts[1])
        color = int(parts[2])
        ops.append((t, idx, color))
    grid = [[0]*m for _ in range(n)]
    for t, idx, color in ops:
        if t == 1:
            row = idx-1
            for col in range(m):
                grid[row][col] = color
        else:
            col = idx-1
            for row in range(n):
                grid[row][col] = color
    output = run(x)
    out_lines = output.strip().split('\n')
    assert len(out_lines) == n
    for i in range(n):
        row_vals = list(map(int, out_lines[i].split()))
        assert len(row_vals) == m
        for j in range(m):
            assert row_vals[j] == grid[i][j]

def test_brute_force_reverse(run, x):
    lines = x.strip().splitlines()
    n, m, k = map(int, lines[0].split())
    ops = []
    for i in range(1, k+1):
        parts = lines[i].split()
        t = int(parts[0])
        idx = int(parts[1])
        color = int(parts[2])
        ops.append((t, idx, color))
    output = run(x)
    out_lines = output.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    for i in range(n):
        for j in range(m):
            color = 0
            for op in reversed(ops):
                t, idx, c = op
                if t == 1 and idx == i+1:
                    color = c
                    break
                if t == 2 and idx == j+1:
                    color = c
                    break
            assert grid[i][j] == color

def test_last_derive(run, x):
    lines = x.strip().splitlines()
    n, m, k = map(int, lines[0].split())
    row_last = [(0, -1)] * n
    col_last = [(0, -1)] * m
    for time_idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        t = int(parts[0])
        idx = int(parts[1])
        color = int(parts[2])
        if t == 1:
            row_last[idx-1] = (color, time_idx)
        else:
            col_last[idx-1] = (color, time_idx)
    output = run(x)
    out_lines = output.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    for i in range(n):
        for j in range(m):
            r_color, r_time = row_last[i]
            c_color, c_time = col_last[j]
            expected = c_color if c_time > r_time else r_color
            assert grid[i][j] == expected

def test_color_range(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        vals = line.split()
        for v in vals:
            val = int(v)
            assert 0 <= val <= 10**9

def test_output_shape(run, x):
