def test_at_least_two_if_n_ge_2(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    out = int(run(x).strip())
    if n >= 2:
        assert out >= 2

def test_whole_array_good_then_output_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if n > 2:
        good = all(a[i] == a[i-1] + a[i-2] for i in range(2, n))
        if good:
            out = int(run(x).strip())
            assert out == n

def test_exists_good_segment_of_length_output(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    found = False
    for l in range(0, n - out + 1):
        r = l + out - 1
        ok = True
        for i in range(l+2, r+1):
            if a[i] != a[i-1] + a[i-2]:
                ok = False
                break
        if ok:
            found = True
            break
    assert found

def test_no_good_segment_longer_than_output(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if out == n:
        return
    for l in range(0, n - (out+1) + 1):
        r = l + out
        ok = True
        for i in range(l+2, r+1):
            if a[i] != a[i-1] + a[i-2]:
                ok = False
                break
        if ok:
            assert False, f"Found good segment of length {out+1}"

def test_lower_bound_from_runs(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if n == 1:
        assert out == 1
    else:
        longest_run = 0
        curr = 0
        for i in range(2, n):
            if a[i] == a[i-1] + a[i-2]:
                curr += 1
                longest_run = max(longest_run, curr)
            else:
                curr = 0
        assert out >= longest_run + 2

def test_upper_bound_from_runs(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if n == 1:
