                curr += 1
                longest_run = max(longest_run, curr)
            else:
                curr = 0
        assert out <= longest_run + 2

def test_brute_force_oracle(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    best = 1
    for l in range(n):
        for r in range(l, n):
            length = r - l + 1
            if length <= 2:
                if length > best:
                    best = length
            else:
                ok = True
                for i in range(l+2, r+1):
                    if a[i] != a[i-1] + a[i-2]:
                        ok = False
                        break
                if ok and length > best:
                    best = length
    out = int(run(x).strip())
    assert out == best

def test_longest_run_oracle(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if n == 1:
        expected = 1
    else:
        longest_run = 0
        curr = 0
        for i in range(2, n):
            if a[i] == a[i-1] + a[i-2]:
                curr += 1
                longest_run = max(longest_run, curr)
            else:
                curr = 0
        expected = longest_run + 2
    out = int(run(x).strip())
    assert out == expected

