def test_bruteforce_small(run, x):
    N = int(x.strip())
    if N > 8:
        return
    import itertools
    max_sum = -1
    for perm in itertools.permutations(range(1, N+1)):
        s = sum(i % p for i, p in enumerate(perm, start=1))
        if s > max_sum:
            max_sum = s
    ans = int(run(x).strip())
    assert ans == max_sum

def test_formula_all(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    expected = N * (N - 1) // 2
    assert ans == expected

