    ans = int(run(x).strip())
    assert ans >= 0

def test_divisible_by_17(run, x):
    N = int(x.strip())
    if N % 17 == 0:
        ans = int(run(x).strip())
        expected = N * (N - 1) // 2
        assert ans == expected

