def test_examples(run, x):
    if x == "2\n1 2\n":
        out = run(x)
        val = float(out.strip())
        assert abs(val - 0.0) <= 1e-6, f'Expected 0.0, got {val}'
    elif x == "3\n1 2 10\n":
        out = run(x)
        val = float(out.strip())
        expected = 2.0 / 27.0
        if abs(val - expected) > 1e-6 * max(1.0, abs(expected)):
            raise AssertionError(f'Expected {expected}, got {val}')

def test_n2_zero(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n == 2:
        out = run(x)
        val = float(out.strip())
        if abs(val) > 1e-6:
            raise AssertionError(f'For n=2 expected 0, got {val}')

def test_probability_range(run, x):
    out = run(x)
    val = float(out.strip())
    if not (0 - 1e-9 <= val <= 1 + 1e-9):
        raise AssertionError(f'Probability {val} out of range [0,1]')

def test_output_is_float(run, x):
    out = run(x)
    s = out.strip()
    try:
        float(s)
    except ValueError:
        raise AssertionError(f'Output {s!r} is not a valid float')

def test_brute_force_n_le_8(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 8:
        return
    vals = list(map(int, lines[1].split()))
    pairs = [(i, j) for i in range(n) for j in range(n) if i != j]
    total = 0
    good = 0
    for a1, j1 in pairs:
        if vals[a1] <= vals[j1]:
            continue
        for a2, j2 in pairs:
            if vals[a2] <= vals[j2]:
                continue
            for a3, j3 in pairs:
                if vals[a3] >= vals[j3]:
                    continue
                total += 1
                sumA = vals[a1] + vals[a2] + vals[a3]
                sumJ = vals[j1] + vals[j2] + vals[j3]
                if sumJ > sumA:
                    good += 1
    expected = good / total if total else 0.0
    out = run(x)
    val = float(out.strip())
    if abs(val - expected) > 1e-6 * max(1.0, abs(expected)):
        raise AssertionError(f'Brute force expects {expected}, got {val}')

def test_formula_n_gt8_le_20(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n <= 8 or n > 20:
        return
    vals = list(map(int, lines[1].split()))
    max_diff = max(vals) - min(vals)
    A = [0] * (max_diff + 2)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            d = vals[i] - vals[j]
            if d > 0:
                A[d] += 1
    W = sum(A)
    if W == 0:
        expected = 0.0
    else:
        C = [0] * (max_diff + 2)
        for i in range(1, max_diff + 1):
            C[i] = C[i-1] + A[i]
        total_A = C[max_diff]
        S = 0
        for i in range(1, max_diff + 1):
            if A[i] == 0:
                continue
            for j in range(1, max_diff + 1):
                if A[j] == 0:
                    continue
                if i + j > max_diff:
                    break
                S += A[i] * A[j] * (total_A - C[i+j])
        expected = S / (W ** 3)
    out = run(x)
    val = float(out.strip())
    if abs(val - expected) > 1e-6 * max(1.0, abs(expected)):
        raise AssertionError(f'Formula expects {expected}, got {val}')

def test_output_length(run, x):
    out = run(x)
    s = out.strip()
    if len(s) > 30:
        raise AssertionError(f'Output length {len(s)} too long')

def test_output_no_space(run, x):
    out = run(x)
    s = out.strip()
    if ' ' in s:
        raise AssertionError('Output contains spaces')

def test_output_not_empty(run, x):
    out = run(x)
    if out.strip() == '':
        raise AssertionError('Output is empty')

def test_output_one_decimal_point(run, x):
    out = run(x)
    s = out.strip()
    if s.count('.') > 1:
        raise AssertionError('More than one decimal point')

