def test_exhaustive_verification(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    n = int(lines[0])
    b = list(map(int, lines[1].split()))
    best = 0
    for mask in range(1, 1 << n):
        subseq = [b[i] for i in range(n) if (mask >> i) & 1]
        k = len(subseq)
        if k <= 1:
            if k > best:
                best = k
        else:
            even_vals = subseq[0::2]
            odd_vals = subseq[1::2]
            if len(set(even_vals)) == 1 and (len(odd_vals) == 0 or len(set(odd_vals)) == 1):
                if k > best:
                    best = k
    assert ans == best

def test_output_range(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    n = int(lines[0])
    assert 1 <= ans <= n

def test_at_least_max_frequency(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    b = list(map(int, lines[1].split()))
    from collections import Counter
    freq = max(Counter(b).values())
    assert ans >= freq

def test_at_least_two_if_n_ge2(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n >= 2:
        assert ans >= 2

def test_alternating_pattern_gives_n(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    b = list(map(int, lines[1].split()))
    n = len(b)
    if n == 0:
        return
    first = b[0]
    second = b[1] if n > 1 else first
    ok = True
    for i in range(n):
        if i % 2 == 0:
            if b[i] != first:
                ok = False
                break
        else:
            if b[i] != second:
                ok = False
                break
    if ok:
        assert ans == n

def test_example1(run, x):
    if x == "2\n3 5\n":
        output = run(x)
        ans = int(output.strip())
        assert ans == 2

def test_example2(run, x):
    if x == "4\n10 20 10 30\n":
        output = run(x)
        ans = int(output.strip())
        assert ans == 3

def test_constant_sequence(run, x):
    output = run(x)
    ans = int(output.strip())
    lines = x.strip().splitlines()
    b = list(map(int, lines[1].split()))
    if len(set(b)) == 1:
        assert ans == len(b)

def test_specific_input_5(run, x):
    if x == "3\n10 20 30\n":
        output = run(x)
        ans = int(output.strip())
        assert ans == 2

def test_specific_input_11(run, x):
    if x == "6\n1 1 1 2 2 2\n":
        output = run(x)
        ans = int(output.strip())
        assert ans == 3

