tests_src:
def test_length(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    assert len(out) == len(s)

def test_digits_unchanged(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    for i, c in enumerate(s):
        if c.isdigit():
            assert out[i] == c

def test_lowercase_remains_lowercase(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    for i, c in enumerate(s):
        if c.isalpha() and c.islower():
            assert out[i].islower()

def test_uppercase_remains_uppercase(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    for i, c in enumerate(s):
        if c.isalpha() and c.isupper():
            assert out[i].isupper()

def test_consistency(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    mapping = {}
    for i, c in enumerate(s):
        if c.isalpha():
            lower_in = c.lower()
            lower_out = out[i].lower()
            if lower_in not in mapping:
                mapping[lower_in] = lower_out
            else:
                assert mapping[lower_in] == lower_out

def test_injectivity(run, x):
    lines = x.strip().split('\n')
    s = lines[2].strip()
    out = run(x).rstrip('\n')
    mapping = {}
    out_set = set()
    for i, c in enumerate(s):
        if c.isalpha():
            lower_in = c.lower()
            lower_out = out[i].lower()
            if lower_in in mapping:
                assert mapping[lower_in] == lower_out
            else:
                assert lower_out not in out_set
                mapping[lower_in] = lower_out
                out_set.add(lower_out)

def test_output_letters_in_layout2(run, x):
    lines = x.strip().split('\n')
    s2 = lines[1].strip()
    out = run(x).rstrip('\n')
    allowed = set(s2)
    for ch in out:
        if ch.isalpha():
            assert ch.lower() in allowed

def test_input_letters_in_layout1(run, x):
    lines = x.strip().split('\n')
    s1 = lines[0].strip()
    s = lines[2].strip()
    allowed = set(s1)
    for ch in s:
        if ch.isalpha():
            assert ch.lower() in allowed

def test_only_letters_digits(run, x):
    out = run(x).rstrip('\n')
    for ch in out:
        assert ch.isalnum()

def test_correct_output(run, x):
    lines = x.strip().split('\n')
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    s = lines[2].strip()
    mapping = {s1[i]: s2[i] for i in range(26)}
    expected = []
    for c in s:
        if c.isalpha():
            lower_c = c.lower()
            mapped = mapping[lower_c]
            if c.isupper():
                expected.append(mapped.upper())
            else:
                expected.append(mapped)
        else:
            expected.append(c)
    expected_str = ''.join(expected)
    out = run(x).rstrip('\n')
    assert out == expected_str

