def test_consistency(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    if any(not (('A' <= c <= 'Z') or ('a' <= c <= 'z') or ('0' <= c <= '9')) for c in s):
        return
    actual = run(x)
    if actual.endswith('\n'):
        actual = actual[:-1]
    if len(actual) != len(s):
        return
    mapping = {}
    for i, c in enumerate(s):
        if 'A' <= c <= 'Z' or 'a' <= c <= 'z':
            if c in mapping:
                assert mapping[c] == actual[i]
            else:
                mapping[c] = actual[i]


