      "source": "def test_queries_same_length_same_answer(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    queries = []
    for i in range(m):
        l, r = map(int, lines[2+i].split())
        k = r - l + 1
        queries.append((i, k))
    output = run(x).strip().split()
    from collections import defaultdict
    groups = defaultdict(list)
    for idx, k in queries:
        groups[k].append(idx)
    for k, indices in groups.items():
        if len(indices) > 1:
            first_val = output[indices[0]]
            for idx in indices[1:]:
                assert output[idx] == first_val, f'Queries with same length {k} have different answers'"
    },
    {
      "name": "test_examples",
      "source": "def test_examples(run, x):
    examples = {
        '2 3\n1 -1\n1 1\n1 2\n2 2\n': '0\n1\n0\n',
        '5 5\n-1 1 1 1 -1\n1 1\n2 3\n3 5\n2 5\n1 5\n': '0\n1\n0\n1\n0\n',
        '1 1\n-1\n1 1\n': '0\n'
    }
    if x in examples:
        output = run(x)
        assert output == examples[x], f'Example input mismatch'"
    },
    {
      "name": "test_no_rearrangement_needed",
      "source": "def test_no_rearrangement_needed(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    arr = list(map(int, lines[1].split()))
    queries = []
    for i in range(m):
        l, r = map(int, lines[2+i].split())
        sub = arr[l-1:r]
        s = sum(sub)
        if s == 0:
            queries.append(i)
    if not queries:
        return
    output = run(x).strip().split()
    for idx in queries:
        assert output[idx] == '1', f'Query {idx} has subarray sum 0, expected 1 got {output[idx]}'"
    },
    {
      "name": "test_all_negative_or_all_positive",
      "source": "def test_all_negative_or_all_positive(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    arr = list(map(int, lines[1].split()))
    cnt1 = arr.count(1)
    cnt_neg = arr.count(-1)
    if cnt1 == 0 or cnt_neg == 0:
        output = run(x).strip().split()
        for i, val in enumerate(output):
            assert val == '0', f'All elements same sign, but query {i} got {val}'"
    },
    {
      "name": "test_max_even_length",
      "source": "def test_max_even_length(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    arr = list(map(int, lines[1].split()))
    cnt1 = arr.count(1)
    cnt_neg = arr.count(-1)
    max_zero = 2 * min(cnt1, cnt_neg)
    queries = []
    for i in range(m):
        l, r = map(int, lines[2+i].split())
        k = r - l + 1
        if k == max_zero:
            queries.append((i, k, '1'))
        if k == max_zero + 2:
            queries.append((i, k, '0'))
    if not queries:
        return
    output = run(x).strip().split()
    for idx, k, exp in queries:
        assert output[idx] == exp, f'Query {idx} length {k} expected {exp} got {output[idx]}'"
    }
  ]
}

