def test_non_negative(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    out = run(x).strip().split()
    assert len(out) == q
    for v in out:
        assert int(v) >= 0

def test_even_total(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        assert (n + a) % 2 == 0

def test_total_ge4(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        assert n + a >= 4

def test_minimal(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        for k in range(a):
            total = n + k
            if total >= 4 and total % 2 == 0:
                assert False, f'Smaller k={k} works for n={n}'

def test_output_in_range(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    out = run(x).strip().split()
    assert len(out) == q
    for v in out:
        assert int(v) in {0, 1, 2}

def test_small_n_specific(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        if n == 2:
            assert a == 2
        elif n == 3:
            assert a == 1
        elif n == 4:
            assert a == 0

def test_large_even(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        if n >= 4 and n % 2 == 0:
            assert a == 0

def test_large_odd(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        if n >= 4 and n % 2 == 1:
            assert a == 1

def test_bruteforce(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        best = None
        for k in (0, 1, 2):
            total = n + k
            if total >= 4 and total % 2 == 0:
                best = k
                break
        assert best is not None
        assert a == best

def test_formula(run, x):
    lines = x.strip().split()
    if not lines:
        return
    q = int(lines[0])
    ns = list(map(int, lines[1:1+q]))
    out = run(x).strip().split()
    assert len(out) == q
    for n, a_str in zip(ns, out):
        a = int(a_str)
        if n < 4:
            expected = 4 - n
        else:
            expected = n % 2
        assert a == expected

