        if a[i] != a[i+1]:
            orig_stress += 1
    filtered = [g for g in a if g != val]
    stress = 0
    for i in range(len(filtered)-1):
        if filtered[i] != filtered[i+1]:
            stress += 1
    assert stress <= orig_stress, f"Stress after removal ({stress}) > original ({orig_stress})"

