            best_genres = [x_cand]
        elif stress == best_stress:
            best_genres.append(x_cand)
    correct = min(best_genres)
    assert val == correct, f"Expected {correct}, got {val}"

def test_no_leading_zeros(run, x):
    out = run(x).strip()
    if out == '0':
        assert False, "Output 0 is invalid"
    if len(out) > 1 and out[0] == '0':
        assert False, "Output has leading zero"

def test_examples(run, x):
