def test_bruteforce(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    s = lines[1].strip()
    positions = [(0,0)]
    xc = yc = 0
    for c in s:
        if c == 'R':
            xc += 1
        else:
            yc += 1
        positions.append((xc, yc))
    coins = 0
    for i in range(1, len(positions)-1):
        if positions[i][0] == positions[i][1]:
            xb, yb = positions[i-1]
            xa, ya = positions[i+1]
            side_before = None
            if xb > yb:
                side_before = 0
            elif xb < yb:
                side_before = 1
            side_after = None
            if xa > ya:
                side_after = 0
            elif xa < ya:
                side_after = 1
            if side_before is not None and side_after is not None and side_before != side_after:
                coins += 1
    expected = coins
    out = run(x)
    out_val = int(out.strip())
    assert out_val == expected

def test_output_format(run, x):
    out = run(x)
    out_stripped = out.strip()
    assert out_stripped.isdigit()
    if out != out_stripped:
        assert out == out_stripped + '\n'

def test_nonnegative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_examples(run, x):
    examples = {"1\nU\n": "0\n", "6\nRURUUR\n": "1\n", "7\nURRRUUU\n": "2\n"}
    if x in examples:
        out = run(x)
        assert out == examples[x]

def test_all_R(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    if all(c == 'R' for c in s):
        out = run(x)
        val = int(out.strip())
        assert val == 0

def test_all_U(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    if all(c == 'U' for c in s):
        out = run(x)
        val = int(out.strip())
        assert val == 0

def test_alternating(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    is_alt = True
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            is_alt = False
            break
    if is_alt and len(s) > 0:
        out = run(x)
        val = int(out.strip())
        assert val == 0

def test_bound_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    out = run(x)
    val = int(out.strip())
    assert val <= n

def test_bound_gate_visits(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    xc = yc = 0
    gate_visits = 0
    for c in s:
        if c == 'R':
            xc += 1
        else:
            yc += 1
        if xc == yc:
            gate_visits += 1
    out = run(x)
    val = int(out.strip())
    assert val <= gate_visits

def test_n_equals_1(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 0

