def test_correct_via_sorted_diffs(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n_k = list(map(int, lines[0].split()))
    if len(n_k) < 2:
        return
    n, k = n_k[0], n_k[1]
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    if n == 1:
        correct = 0
    else:
        diffs = [a[i+1] - a[i] for i in range(n-1)]
        diffs.sort()
        need = n - k
        correct = sum(diffs[:need])
    out = run(x).strip()
    if out == '':
        assert False, 'empty output'
    ans = int(out)
    assert ans == correct, f'Expected {correct}, got {ans}'

def test_correct_via_total_span_minus_largest(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    total_span = a[-1] - a[0]
    if k == 1:
        correct = total_span
    else:
        diffs = [a[i+1] - a[i] for i in range(n-1)]
        diffs.sort(reverse=True)
        sum_largest = sum(diffs[:k-1])
        correct = total_span - sum_largest
    out = run(x).strip()
    ans = int(out)
    assert ans == correct, f'Expected {correct}, got {ans}'

def test_correct_for_small_n_brute(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    if n > 10:
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    from itertools import combinations
    if k == 1:
        correct = a[-1] - a[0]
    else:
        best = float('inf')
        for splits in combinations(range(1, n), k-1):
            splits = list(splits)
            splits.sort()
            cost = 0
            start = 0
            for end in splits:
                sub = a[start:end]
                cost += sub[-1] - sub[0]
                start = end
            sub = a[start:]
            cost += sub[-1] - sub[0]
            if cost < best:
                best = cost
        correct = best
    out = run(x).strip()
    ans = int(out)
    assert ans == correct, f'Expected {correct}, got {ans}'

def test_output_is_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, 'output not an integer'

def test_output_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'output negative'

def test_output_not_exceed_total_span(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    total_span = a[-1] - a[0]
    out = run(x).strip()
    ans = int(out)
    assert ans <= total_span, f'output {ans} exceeds total span {total_span}'

def test_cost_zero_when_k_n(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    if k != n:
        return
    out = run(x).strip()
    ans = int(out)
    assert ans == 0, f'cost must be 0 when k=n, got {ans}'

def test_cost_total_span_when_k_1(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    if k != 1:
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    total_span = a[-1] - a[0]
    out = run(x).strip()
    ans = int(out)
    assert ans == total_span, f'cost must be total span when k=1, got {ans} expected {total_span}'

def test_output_format_single_integer(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped.isdigit(), 'output not a non-negative integer'
    assert out.rstrip() == stripped, 'extra whitespace in output'

def test_output_achievable_for_small_n(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    if n > 15:
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    out = run(x).strip()
    ans = int(out)
    total_span = a[-1] - a[0]
    target_gap_sum = total_span - ans
    diffs = [a[i+1] - a[i] for i in range(n-1)]
    from itertools import combinations
    found = False
    for comb in combinations(diffs, k-1):
        if sum(comb) == target_gap_sum:
            found = True
            break
    assert found, f'output {ans} not achievable by any partition'

