def test_feasibility_of_output(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    m, n, k, t = first
    soldiers = list(map(int, lines[1].split()))
    out = run(x)
    ans = int(out.strip())
    if ans == 0:
        return
    if ans > len(soldiers):
        assert False, f"Answer {ans} exceeds number of soldiers {len(soldiers)}"
    sorted_ag = sorted(soldiers, reverse=True)
    ath_largest = sorted_ag[ans-1]
    def time_needed(threshold):
        intervals = []
        for i in range(k):
            l, r, d = map(int, lines[2+i].split())
            if d > threshold:
                intervals.append((l-1, r))
        if not intervals:
            return n+1
        intervals.sort()
        length = 0
        cur_start, cur_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= cur_end:
                cur_end = max(cur_end, end)
            else:
                length += cur_end - cur_start
                cur_start, cur_end = start, end
        length += cur_end - cur_start
        return n+1 + 2*length
    needed = time_needed(ath_largest)
    assert needed <= t, f"Subset of size {ans} with min agility {ath_largest} requires {needed} > {t}, so impossible"

def test_full_oracle(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    m, n, k, t = first
    soldiers = list(map(int, lines[1].split()))
    traps = []
    for i in range(k):
