def test_bruteforce_small(run, x):
    import itertools, math
    n = int(x.strip())
    if n > 9:
        return
    MOD = 10**9+7
    ans = int(run(x).strip())
    best = 0
    cnt = 0
    for perm in itertools.permutations(range(1, n+1)):
        g = 0
        distinct = set()
        for v in perm:
            g = math.gcd(g, v)
            distinct.add(g)
        f = len(distinct)
        if f > best:
            best = f
            cnt = 1
        elif f == best:
            cnt += 1
    assert ans == cnt % MOD

def test_dp_small(run, x):
    import math
    n = int(x.strip())
    if n > 15:
        return
    MOD = 10**9+7
    ans = int(run(x).strip())
    full = (1 << n) - 1
    dp = [dict() for _ in range(1 << n)]
    for i in range(n):
        mask = 1 << i
        dp[mask][(i+1, 1)] = 1
    for mask in range(1 << n):
        for (g, d), ways in dp[mask].items():
            for i in range(n):
                if not (mask >> i) & 1:
                    xv = i+1
                    ng = math.gcd(g, xv)
                    nd = d + (1 if ng != g else 0)
                    nmask = mask | (1 << i)
                    dp[nmask][(ng, nd)] = dp[nmask].get((ng, nd), 0) + ways
    maxd = 0
    for (g, d) in dp[full].keys():
        if d > maxd:
            maxd = d
    total = 0
    for (g, d), ways in dp[full].items():
        if d == maxd:
            total += ways
    assert ans == total % MOD

def test_example_2(run, x):
    n = int(x.strip())
    if n != 2:
        return
    assert run(x).strip() == '1'

def test_example_3(run, x):
    n = int(x.strip())
    if n != 3:
        return
    assert run(x).strip() == '4'

def test_example_6(run, x):
    n = int(x.strip())
    if n != 6:
        return
    assert run(x).strip() == '120'

def test_example_4(run, x):
    n = int(x.strip())
    if n != 4:
        return
    assert run(x).strip() == '2'

def test_example_8(run, x):
    n = int(x.strip())
    if n != 8:
        return
    assert run(x).strip() == '240'

def test_example_12(run, x):
    import math
    n = int(x.strip())
    if n != 12:
        return
    MOD = 10**9+7
    ans = int(run(x).strip())
    full = (1 << n) - 1
    dp = [dict() for _ in range(1 << n)]
    for i in range(n):
        mask = 1 << i
        dp[mask][(i+1, 1)] = 1
    for mask in range(1 << n):
        for (g, d), ways in dp[mask].items():
            for i in range(n):
                if not (mask >> i) & 1:
                    xv = i+1
                    ng = math.gcd(g, xv)
                    nd = d + (1 if ng != g else 0)
                    nmask = mask | (1 << i)
                    dp[nmask][(ng, nd)] = dp[nmask].get((ng, nd), 0) + ways
    maxd = 0
    for (g, d) in dp[full].keys():
        if d > maxd:
            maxd = d
    total = 0
    for (g, d), ways in dp[full].items():
        if d == maxd:
            total += ways
    assert ans == total % MOD

def test_output_valid(run, x):
    out = run(x)
    assert out.endswith('\n') or '\n' not in out  # single line
    s = out.strip()
    assert s == out.rstrip('\n')  # no extra whitespace besides possibly trailing newline
    assert len(s) > 0
    if s != '0':
        assert s[0] != '0'
    val = int(s)
    assert 0 <= val < 10**9+7

def test_large_not_zero(run, x):
    n = int(x.strip())
    if n != 1000000:
        return
    out = run(x).strip()
    assert out != '0'

