def test_symmetry_flip(run, x):
    def min_flips_dp(s):
        n = len(s)
        arr = [0 if c=='L' else 1 for c in s]
        INF = 10**9
        ans = INF
        for t0 in (0,1):
            for t1 in (0,1):
                dp = [[INF]*2 for _ in range(2)]
                dp[t0][t1] = (arr[0]!=t0) + (arr[1]!=t1)
                for i in range(2, n):
                    new_dp = [[INF]*2 for _ in range(2)]
                    for a in (0,1):
                        for b in (0,1):
                            if dp[a][b] == INF: continue
                            for c in (0,1):
                                if a == c:
                                    if b != 1 - a:
                                        continue
                                cost = dp[a][b] + (arr[i]!=c)
                                if cost < new_dp[b][c]:
                                    new_dp[b][c] = cost
                    dp = new_dp
                for a in (0,1):
                    for b in (0,1):
                        if dp[a][b] == INF: continue
                        if a == t0 and b != 1 - a:
                            continue
                        if b == t1 and t0 != 1 - b:
                            continue
                        ans = min(ans, dp[a][b])
        return ans
    lines = x.strip().splitlines()
    s = lines[2].strip()
    s_flip = ''.join('L' if c=='R' else 'R' for c in s)
    expected_flip = min_flips_dp(s_flip)
    out = run(x).strip()
    ans = int(out)
    assert ans == expected_flip

