def test_lower_bound(run, x):
    lines = x.strip().splitlines()
    s = lines[2].strip()
    n = len(s)
    groups = []
    cnt = 0
    cur = s[0]
    for ch in s:
        if ch == cur:
            cnt += 1
        else:
            groups.append(cnt)
            cur = ch
            cnt = 1
    if groups:
        if s[0] == s[-1]:
            groups[0] += cnt
        else:
            groups.append(cnt)
    else:
        groups.append(cnt)
    lower = sum(v // 3 for v in groups)
    out = run(x).strip()
    ans = int(out)
    assert ans >= lower

