def test_n2(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n != 2:
        return
    s = lines[1]
    # check validity: number of '?' even
    if s.count('?') % 2 != 0:
        return
    # compute correct answer by DP
    from functools import lru_cache
    left_sum = 0
    left_q = 0
    right_sum = 0
    right_q = 0
    for i in range(n):
        if i < n//2:
            if s[i] == '?':
                left_q += 1
            else:
                left_sum += int(s[i])
        else:
            if s[i] == '?':
                right_q += 1
            else:
                right_sum += int(s[i])
    @lru_cache(None)
    def dp(left_sum, right_sum, left_q, right_q, turn):
        if left_q == 0 and right_q == 0:
            return "Bicarp" if left_sum == right_sum else "Monocarp"
        if turn == 0:  # Monocarp
            win = False
            # try all moves
            if left_q > 0:
                for d in range(10):
                    if dp(left_sum + d, right_sum, left_q - 1, right_q, 1) == "Monocarp":
                        win = True
                        break
                if not win and right_q > 0:
                    for d in range(10):
                        if dp(left_sum, right_sum + d, left_q, right_q - 1, 1) == "Monocarp":
                            win = True
                            break
            else:
                if right_q > 0:
                    for d in range(10):
                        if dp(left_sum, right_sum + d, left_q, right_q - 1, 1) == "Monocarp":
                            win = True
                            break
            return "Monocarp" if win else "Bicarp"
        else:  # Bicarp
            win = False
            if left_q > 0:
                for d in range(10):
                    if dp(left_sum + d, right_sum, left_q - 1, right_q, 0) == "Bicarp":
                        win = True
                        break
                if not win and right_q > 0:
                    for d in range(10):
                        if dp(left_sum, right_sum + d, left_q, right_q - 1, 0) == "Bicarp":
                            win = True
                            break
            else:
                if right_q > 0:
                    for d in range(10):
                        if dp(left_sum, right_sum + d, left_q, right_q - 1, 0) == "Bicarp":
                            win = True
                            break
            return "Bicarp" if win else "Monocarp"
    correct = dp(left_sum, right_sum, left_q, right_q, 0)
    output = run(x)
    assert output.strip() == correct.strip()

