def test_n2(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n != 2:
        return
    s = lines[1]
    if s.count('?') % 2 != 0:
        return
    left_sum = 0
    left_q = 0
    right_sum = 0
    right_q = 0
    for i in range(n):
        if i < n//2:
            if s[i] == '?':
                left_q += 1
            else:
                left_sum += int(s[i])
        else:
            if s[i] == '?':
                right_q += 1
            else:
                right_sum += int(s[i])
    from functools import lru_cache
    @lru_cache(None)
    def dp(l, r, lq, rq, turn):
        if lq == 0 and rq == 0:
            return "Bicarp" if l == r else "Monocarp"
        if turn == 0:
            win = False
            if lq > 0:
                for d in range(10):
                    if dp(l + d, r, lq - 1, rq, 1) == "Monocarp":
                        win = True
                        break
                if not win and rq > 0:
                    for d in range(10):
                        if dp(l, r + d, lq, rq - 1, 1) == "Monocarp":
                            win = True
                            break
            else:
                if rq > 0:
                    for d in range(10):
                        if dp(l, r + d, lq, rq - 1, 1) == "Monocarp":
                            win = True
                            break
            return "Monocarp" if win else "Bicarp"
        else:
            win = False
            if lq > 0:
                for d in range(10):
                    if dp(l + d, r, lq - 1, rq, 0) == "Bicarp":
                        win = True
                        break
                if not win and rq > 0:
                    for d in range(10):
                        if dp(l, r + d, lq, rq - 1, 0) == "Bicarp":
                            win = True
                            break
            else:
                if rq > 0:
                    for d in range(10):
                        if dp(l, r + d, lq, rq - 1, 0) == "Bicarp":
                            win = True
                            break
            return "Bicarp" if win else "Monocarp"
    correct = dp(left_sum, right_sum, left_q, right_q, 0)
    assert output.strip() == correct.strip()

