def test_oracle(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s:
        if s.count('*') > 1:
            match = False
        else:
            prefix, suffix = s.split('*')
            match = t.startswith(prefix) and t.endswith(suffix) and len(t) >= len(prefix) + len(suffix)
    else:
        match = s == t
    expected = "YES" if match else "NO"
    out = run(x).strip()
    assert out == expected

def test_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n")

def test_no_star(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' not in s:
        out = run(x).strip()
        expected = "YES" if s == t else "NO"
        assert out == expected

def test_prefix(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s and s.count('*') == 1:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == "YES":
            assert t.startswith(prefix)

def test_suffix(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s and s.count('*') == 1:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == "YES":
            assert t.endswith(suffix)

def test_length(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s and s.count('*') == 1:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == "YES":
            assert len(t) >= len(prefix) + len(suffix)

def test_no_condition(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s and s.count('*') == 1:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == "NO":
            assert (not t.startswith(prefix)) or (not t.endswith(suffix)) or (len(t) < len(prefix) + len(suffix))

def test_empty_wildcard(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    s = lines[1].strip()
    t = lines[2].strip()
    if '*' in s and s.count('*') == 1:
        prefix, suffix = s.split('*')
        if t == prefix + suffix:
            out = run(x).strip()
            assert out == "YES"

def test_star_start(run, x):
    lines = x.strip().splitlines()
