def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    int(s)  # must be integer


def test_bounds(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = run(x)
    s = int(out.strip())
    assert 0 <= s <= n * m


def test_zero_iff_min_product_gt_x(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    min_product = min(a) * min(b)
    assert (s == 0) == (min_product > x_val)


def test_whole_matrix_if_x_large(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    total_product = sum(a) * sum(b)
    if x_val >= total_product:
        assert s == n * m


def test_at_least_one_rectangle(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    if s == 0:
        return
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    found = False
    for x1 in range(n):
        for x2 in range(x1, n):
            sum_a = pref_a[x2+1] - pref_a[x1]
            for y1 in range(m):
                for y2 in range(y1, m):
                    area = (x2 - x1 + 1) * (y2 - y1 + 1)
                    if area == s:
                        sum_b = pref_b[y2+1] - pref_b[y1]
                        if sum_a * sum_b <= x_val:
                            found = True
                            break
                if found:
                    break
            if found:
                break
        if found:
            break
    assert found, f'No rectangle of area {s} with sum <= {x_val}'


def test_no_larger_rectangle(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    if s == n * m:
        return
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    possible = False
    for x1 in range(n):
        for x2 in range(x1, n):
            sum_a = pref_a[x2+1] - pref_a[x1]
            for y1 in range(m):
                for y2 in range(y1, m):
                    area = (x2 - x1 + 1) * (y2 - y1 + 1)
                    if area == s + 1:
                        sum_b = pref_b[y2+1] - pref_b[y1]
                        if sum_a * sum_b <= x_val:
                            possible = True
                            break
                if possible:
                    break
            if possible:
                break
        if possible:
            break
    assert not possible, f'Found rectangle of area {s+1} with sum <= {x_val}'


def test_brute_force_max(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    max_area = 0
    for x1 in range(n):
        for x2 in range(x1, n):
            sum_a = pref_a[x2+1] - pref_a[x1]
            for y1 in range(m):
                for y2 in range(y1, m):
                    sum_b = pref_b[y2+1] - pref_b[y1]
                    if sum_a * sum_b <= x_val:
                        area = (x2 - x1 + 1) * (y2 - y1 + 1)
                        if area > max_area:
                            max_area = area
    assert s == max_area, f'Expected {max_area}, got {s}'


def test_positive_if_min_product_le_x(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    min_product = min(a) * min(b)
    if min_product <= x_val:
        assert s >= 1


def test_existence_of_dimensions_with_min_product(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x)
    s = int(out.strip())
    if s == 0:
        return
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    min_sum_a = [float('inf')] * (n + 1)
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            ssum = pref_a[start+length] - pref_a[start]
            if ssum < min_sum_a[length]:
                min_sum_a[length] = ssum
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    min_sum_b = [float('inf')] * (m + 1)
    for length in range(1, m + 1):
        for start in range(m - length + 1):
            ssum = pref_b[start+length] - pref_b[start]
            if ssum < min_sum_b[length]:
                min_sum_b[length] = ssum
    found = False
    for r in range(1, n + 1):
        if s % r != 0:
            continue
        c = s // r
        if c < 1 or c > m:
            continue
        if min_sum_a[r] * min_sum_b[c] <= x_val:
            found = True
            break
    assert found, f'No dimensions r*c={s} have minimal product <= {x_val}'


def test_1D_case(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    if n != 1 and m != 1:
        return
    out = run(x)
    s = int(out.strip())
    if n == 1:
        max_len = 0
        pref_b = [0]
        for v in b:
            pref_b.append(pref_b[-1] + v)
        for l in range(1, m + 1):
            ok = False
            for start in range(m - l + 1):
                if pref_b[start+l] - pref_b[start] <= x_val // a[0]:
                    ok = True
                    break
            if ok:
                max_len = l
            else:
                break
        assert s == max_len, f'For n=1, expected {max_len}, got {s}'
    else:  # m == 1
        max_len = 0
        pref_a = [0]
        for v in a:
            pref_a.append(pref_a[-1] + v)
        for l in range(1, n + 1):
            ok = False
            for start in range(n - l + 1):
                if pref_a[start+l] - pref_a[start] <= x_val // b[0]:
                    ok = True
                    break
            if ok:
                max_len = l
            else:
                break
        assert s == max_len, f'For m=1, expected {max_len}, got {s}'

