    },
    {
      "name": "test_n0_ai0_implies_one",
      "source": "def test_n0_ai0_implies_one(run, x):
    lines = x.strip().splitlines()
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
