def test_full_bfs_oracle(run, x):
    from collections import deque
    lines = x.strip().splitlines()
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    a_vals = list(map(int, lines[1].split()))
    b_set = set(a - n for a in a_vals)
    if 0 in b_set:
        expected = 1
    else:
        dist = {0: 0}
        q = deque([0])
        found = None
        while q and found is None:
            u = q.popleft()
            d = dist[u]
            if d >= 2000:          # step limit sufficient for given inputs
                continue
            for b in b_set:
                v = u + b
                if v == 0:
                    found = d + 1
                    break
                if v not in dist:
                    dist[v] = d + 1
                    q.append(v)
        expected = found if found is not None else -1
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'
    assert val == expected, f'Expected {expected}, got {val}'

