def test_consistency_formula(run, x):
    MOD = 10**9 + 7
    N, K = map(int, x.split())
    divisors = []
    i = 1
    while i * i <= N:
        if N % i == 0:
            divisors.append(i)
            if i * i != N:
                divisors.append(N // i)
        i += 1
    divisors.sort()
