def test_brute_force_small(run, x):
    import sys
    N, K = map(int, x.strip().split())
    half = (N + 1) // 2
    LIMIT = 500000
    if K != 1:
        val = 1
        for _ in range(half):
            val *= K
            if val > LIMIT:
                return
    from itertools import product
    MOD = 10**9+7
    palindromes = []
    for tup in product(range(1, K+1), repeat=half):
        if N % 2 == 0:
            seq = list(tup) + list(reversed(tup))
        else:
            seq = list(tup[:-1]) + [tup[-1]] + list(reversed(tup[:-1]))
        palindromes.append(tuple(seq))
    seen = set()
    for seq in palindromes:
        for shift in range(N):
            rot = tuple(seq[(i+shift)%N] for i in range(N))
            seen.add(rot)
    expected = len(seen) % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_dihedral_inclusion_exclusion_small(run, x):
    N, K = map(int, x.strip().split())
    if N > 12:
        return
    MOD = 10**9+7
    from collections import deque
    total = 0
    for mask in range(1, 1<<N):
        gens = [s for s in range(N) if (mask>>s)&1]
        elements = set()
        q = deque()
        elements.add((1,0))
        q.append((1,0))
        for s in gens:
            g = (-1, s)
            if g not in elements:
                elements.add(g)
                q.append(g)
        while q:
            sign, shift = q.popleft()
            for s in gens:
                new_sign = sign * -1
                new_shift = (sign * s + shift) % N
                g = (new_sign, new_shift)
                if g not in elements:
                    elements.add(g)
                    q.append(g)
        visited = [False]*N
        orbit_count = 0
        for i in range(N):
            if not visited[i]:
                orbit_count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    idx = stack.pop()
                    for sign, shift in elements:
                        new_idx = (sign * idx + shift) % N
                        if not visited[new_idx]:
                            visited[new_idx] = True
                            stack.append(new_idx)
        fixed = pow(K, orbit_count, MOD)
        if len(gens) % 2 == 1:
            total = (total + fixed) % MOD
        else:
            total = (total - fixed) % MOD
    expected = total % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_N1(run, x):
    N, K = map(int, x.strip().split())
    if N != 1:
        return
    ans = int(run(x).strip())
