def test_prime_N(run, x):
    N, K = map(int, x.strip().split())
    primes = {2,3,5,7,13,1000000007,999999937}
    if N not in primes:
        return
    MOD = 10**9+7
    v1 = K % MOD
    half = (N+1)//2
    vN = (pow(K, half, MOD) - v1) % MOD
    if N % 2 == 1:
        expected = (v1 + vN * N) % MOD
    else:
        expected = (v1 + vN * (N//2)) % MOD
    ans = int(run(x).strip())
    assert ans == expected

