def test_brute_force_small(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    N = int(lines[0])
    if N > 10:
        return
    S1 = lines[1].strip()
    S2 = lines[2].strip()
    letter_to_pos = {}
    for r, row in enumerate((S1, S2)):
        for c, ch in enumerate(row):
            letter_to_pos.setdefault(ch, []).append((r, c))
    letters = list(letter_to_pos.keys())
    dom_id = {ch: i for i, ch in enumerate(letters)}
    adj = set()
    for ch, pos_list in letter_to_pos.items():
        for (r, c) in pos_list:
            if c + 1 < N:
                neighbor_ch = S1[c+1] if r == 0 else S2[c+1]
                if neighbor_ch != ch:
                    u, v = dom_id[ch], dom_id[neighbor_ch]
                    if u != v:
                        adj.add((min(u, v), max(u, v)))
            if r == 0:
                neighbor_ch = S2[c]
                if neighbor_ch != ch:
                    u, v = dom_id[ch], dom_id[neighbor_ch]
                    if u != v:
                        adj.add((min(u, v), max(u, v)))
    total = 0
    for mask in range(3**N):
        colors = []
        tmp = mask
        for i in range(N):
            colors.append(tmp % 3)
            tmp //= 3
        ok = True
        for u, v in adj:
            if colors[u] == colors[v]:
                ok = False
                break
        if ok:
            total += 1
    expected = total % (10**9+7)
    out = run(x).strip()
    got = int(out) % (10**9+7)
    assert got == expected

def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit() and len(out) > 0
    val = int(out)
    mod = 10**9+7
    assert 0 <= val < mod

def test_positive(run, x):
    out = run(x).strip()
    val = int(out)
    assert val > 0

def test_all_vertical(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    S1 = lines[1].strip()
    S2 = lines[2].strip()
    if all(S1[i] == S2[i] for i in range(N)):
        mod = 10**9+7
        expected = 3 * pow(2, N-1, mod) % mod
        out = run(x).strip()
        got = int(out) % mod
        assert got == expected

def test_single_domino(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    if N == 1:
        out = run(x).strip()
        assert out == '3'

def test_two_vertical(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    if N == 2:
        S1 = lines[1].strip()
        S2 = lines[2].strip()
        if S1[0] == S2[0] and S1[1] == S2[1]:
            out = run(x).strip()
            assert out == '6'

def test_two_horizontal_stacked(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    if N == 2:
        S1 = lines[1].strip()
        S2 = lines[2].strip()
        if S1[0] == S1[1] and S2[0] == S2[1] and S1[0] != S2[0]:
            out = run(x).strip()
            assert out == '6'

def test_modulo_reduced(run, x):
    out = run(x).strip()
    val = int(out)
    mod = 10**9+7
    assert val == val % mod

def test_divisible_by_3(run, x):
    out = run(x).strip()
    val = int(out)
    assert val % 3 == 0

def test_sample(run, x):
    if x == '3\naab\nccb\n':
        out = run(x).strip()
        assert out == '6'

