tests_src:
def test_exact_formula(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    prev = 0
    ans = 0
    for val in h:
        if val > prev:
            ans += val - prev
        prev = val
    output = run(x).strip()
    assert output == str(ans)

def test_n1_case(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if n != 1:
        return
    if len(tokens) < 2:
        return
    h_val = int(tokens[1])
    output = run(x).strip()
    assert output == str(h_val)

def test_all_zero(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    if all(v == 0 for v in h):
        output = run(x).strip()
        assert output == "0"

def test_non_decreasing(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    for i in range(n - 1):
        if h[i] > h[i + 1]:
            return
    expected = h[-1] if n > 0 else 0
    output = run(x).strip()
    assert output == str(expected)

def test_non_increasing(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    for i in range(n - 1):
        if h[i] < h[i + 1]:
            return
    expected = h[0] if n > 0 else 0
    output = run(x).strip()
    assert output == str(expected)

def test_output_integer_nonnegative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_output_leq_sum(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    total = sum(h)
    output = run(x).strip()
    val = int(output)
    assert val <= total

def test_output_geq_max(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    if n == 0:
        return
    mx = max(h)
    output = run(x).strip()
    val = int(output)
    assert val >= mx

def test_greedy_simulation(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    arr = h[:]
    ops = 0
    while any(v > 0 for v in arr):
        i = 0
        while i < n:
            if arr[i] == 0:
                i += 1
            else:
                ops += 1
                j = i
                while j < n and arr[j] > 0:
                    j += 1
                for k in range(i, j):
                    arr[k] -= 1
                i = j
    output = run(x).strip()
    assert output == str(ops)

def test_formula_n2(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if n != 2:
        return
    if len(tokens) < 3:
        return
    h = list(map(int, tokens[1:3]))
    expected = h[0] + max(0, h[1] - h[0])
    output = run(x).strip()
    assert output == str(expected)

