        return
    if K <= A:
        out = run(x)
        val = int(out.strip())
        assert val == K

def test_K_between_A_and_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if A < K <= A + B:
        out = run(x)
        val = int(out.strip())
        assert val == A

def test_K_gt_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if K > A + B:
        out = run(x)
        val = int(out.strip())
        expected = A - (K - A - B)
