def test_full_oracle(run, x):
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    routes = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        routes.append((c,t))
    valid_costs = [c for c,t in routes if t <= T]
    if not valid_costs:
        expected = 'TLE'
    else:
        expected = str(min(valid_costs))
    output = run(x).strip()
    assert output == expected, f'Expected {expected}, got {output}'

def test_output_format(run, x):
    output = run(x).strip()
    if output == 'TLE':
        return
    try:
        int(output)
    except ValueError:
        assert False, f'Output is not integer nor TLE: {output}'

def test_output_is_valid_cost_if_integer(run, x):
    output = run(x).strip()
    if output == 'TLE':
        return
    cost = int(output)
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    assert cost in valid_costs, f'Output cost {cost} not among valid costs {valid_costs}'

def test_output_le_all_valid_costs(run, x):
    output = run(x).strip()
    if output == 'TLE':
        return
    cost = int(output)
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    if valid_costs:
        assert all(cost <= c for c in valid_costs), f'Output cost {cost} not <= all valid costs {valid_costs}'
    else:
        assert False, 'Output integer but no valid routes'

def test_if_valid_exists_output_not_tle(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_exists = False
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_exists = True
            break
    if valid_exists:
        assert output != 'TLE', f'Valid routes exist but output is TLE'

def test_if_tle_then_no_valid(run, x):
    output = run(x).strip()
    if output != 'TLE':
        return
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_exists = False
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_exists = True
            break
    assert not valid_exists, f'Output is TLE but valid routes exist'

def test_output_in_range(run, x):
    output = run(x).strip()
    if output == 'TLE':
        return
    cost = int(output)
    assert 1 <= cost <= 1000, f'Cost {cost} out of range 1..1000'

def test_single_valid_route(run, x):
