        if t <= T:
            valid_exists = True
            break
    if not valid_exists:
        out = run(x).rstrip()
        assert out == "TLE", "When no route satisfies t_i <= T, must output 'TLE'"


def test_if_valid_route_then_integer(run, x):
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    valid_exists = False
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_exists = True
            break
    if valid_exists:
        out = run(x).rstrip()
        try:
            int(out)
        except ValueError:
            assert False, "When there is a valid route, output must be an integer"


def test_output_integer_is_valid_cost(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        return
    out_int = int(out)
