        valid_exists = False
        for i in range(1, N+1):
            c, t = map(int, lines[i].split())
            if t <= T:
                valid_exists = True
                break
        assert not valid_exists, "Output is 'TLE' but there exists a valid route"


def test_correct_answer(run, x):
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    if valid_costs:
        expected = str(min(valid_costs))
    else:
