def test_output_is_1_or_2(run, x):
    out = run(x).strip()
    if out == '':
        assert False, 'empty output'
    lines = out.splitlines()
    for line in lines:
        s = line.strip()
        assert s in ('1', '2'), f'output line not 1 or 2: {s}'

def test_output_line_count(run, x):
    lines_in = x.strip().splitlines()
    if not lines_in:
        return
    q = int(lines_in[0].strip())
    out = run(x).strip()
    out_lines = out.splitlines() if out else []
    assert len(out_lines) == q, f'expected {q} lines, got {len(out_lines)}'

def test_no_consecutive_pair_implies_1(run, x):
    def has_consecutive(arr):
        s = set(arr)
        for a in arr:
            if a+1 in s or a-1 in s:
                return True
        return False
    lines = x.strip().splitlines()
    it = iter(lines)
    q = int(next(it).strip())
    queries = []
    for _ in range(q):
        n = int(next(it).strip())
        arr = list(map(int, next(it).strip().split()))
        queries.append(arr)
    out = run(x).strip()
    out_lines = out.splitlines()
    for i, arr in enumerate(queries):
        if not has_consecutive(arr):
            assert out_lines[i].strip() == '1', f'Query {i} should be 1'

def test_consecutive_pair_implies_2(run, x):
