def test_brute_force(run, x):
    a,b,c = map(int, x.strip().split())
    possible = any((a * k) % b == c for k in range(1, b + 1))
    expected = 'YES' if possible else 'NO'
    assert run(x).strip() == expected

def test_gcd_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    d = math.gcd(a, b)
    expected = 'YES' if c % d == 0 else 'NO'
    assert run(x).strip() == expected

def test_c_zero_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if c == 0:
        assert run(x).strip() == 'YES'

def test_gcd_one_always_yes(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    if math.gcd(a, b) == 1:
        assert run(x).strip() == 'YES'

def test_b_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if b == 1:
        assert run(x).strip() == 'YES'

def test_a_multiple_b(run, x):
    a,b,c = map(int, x.strip().split())
    if a % b == 0:
        expected = 'YES' if c == 0 else 'NO'
        assert run(x).strip() == expected

