    output = run(x).strip()
    assert output in ('YES', 'NO')

def test_necessary_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if output == 'YES':
        d = math.gcd(a, b)
        assert c % d == 0

def test_sufficient_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    d = math.gcd(a, b)
    if c % d == 0:
        assert run(x).strip() == 'YES'

def test_a_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if a == 1:
        assert run(x).strip() == 'YES'

