def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_positive(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 1, 'At least one balloon must fit'

def test_range(run, x):
    r, h = map(int, x.strip().split())
    n = h // r
    out = run(x)
    ans = int(out.strip())
    assert 2 * n + 1 <= ans <= 2 * n + 3, f'Answer must be in [{2*n+1}, {2*n+3}]'

def test_examples(run, x):
    out = run(x)
    if x == '1 1\n':
        assert out.strip() == '3', 'Example 1 1 -> 3'
    elif x == '1 2\n':
        assert out.strip() == '5', 'Example 1 2 -> 5'
    elif x == '2 1\n':
        assert out.strip() == '2', 'Example 2 1 -> 2'

def test_backdoor(run, x):
    if x == '2 4\n':
        out = run(x)
        assert out.strip() == '5', 'For r=2, h=4 the correct answer is 5'

def test_multiple(run, x):
    r, h = map(int, x.strip().split())
    if h % r == 0:
        out = run(x)
        ans = int(out.strip())
        n = h // r
        assert ans == 2 * n + 1, f'When h is a multiple of r, answer must be {2*n+1}'

def test_small_d(run, x):
    r, h = map(int, x.strip().split())
    n = h // r
    d = h % r
    if 2 * d < r:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 1, f'When 2*d < r, answer must be {2*n+1}'

def test_medium_d(run, x):
    r, h = map(int, x.strip().split())
    n = h // r
    d = h % r
    if 2 * d >= r and 4 * d * d < 3 * r * r:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 2, f'When r/2 <= d < sqrt(3)/2*r, answer must be {2*n+2}'

def test_large_d(run, x):
    r, h = map(int, x.strip().split())
    n = h // r
    d = h % r
    if 4 * d * d >= 3 * r * r:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 3, f'When d >= sqrt(3)/2*r, answer must be {2*n+3}'

def test_full_oracle(run, x):
    r, h = map(int, x.strip().split())
    n = h // r
    d = h % r
    if 2 * d < r:
        correct = 2 * n + 1
    elif 4 * d * d >= 3 * r * r:
        correct = 2 * n + 3
    else:
        correct = 2 * n + 2
    out = run(x)
    ans = int(out.strip())
    assert ans == correct, f'Expected {correct}, got {ans}'

