    assert ans > 0

def test_form(run, x):
    r, h = map(int, x.strip().split())
    q = h // r
    ans = int(run(x).strip())
    t = ans - 2 * q
    assert t in {1, 2, 3}

def test_small_remainder(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d < r:
        assert ans == 2 * q + 1

def test_medium_remainder(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d >= r and 4 * d * d < 3 * r * r:
        assert ans == 2 * q + 2

