    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 4 * d * d >= 3 * r * r:
        assert ans == 2 * q + 3

def test_full_oracle(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d < r:
        expected = 2 * q + 1
    elif 4 * d * d < 3 * r * r:
        expected = 2 * q + 2
    else:
        expected = 2 * q + 3
    assert ans == expected

def test_lower_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    assert ans >= 2 * q + 1

def test_upper_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    assert ans <= 2 * q + 3

def test_examples(run, x):
    out = run(x)
    inp = x.strip()
    if inp == "1 1":
        assert out == "3\n"
    elif inp == "1 2":
        assert out == "5\n"
    elif inp == "2 1":
        assert out == "2\n"

