def test_correct_oracle(run, x):
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    def days_in_month(y, m):
        if m == 2:
            return 29 if is_leap(y) else 28
        if m in (1,3,5,7,8,10,12):
            return 31
        return 30
    def date_to_days(y, m, d):
        days = 0
        for year in range(1900, y):
            days += 366 if is_leap(year) else 365
        for month in range(1, m):
            days += days_in_month(y, month)
        days += d - 1
        return days
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    date1 = lines[0].strip()
    date2 = lines[1].strip()
    y1,m1,d1 = map(int, date1.split(':'))
    y2,m2,d2 = map(int, date2.split(':'))
    days1 = date_to_days(y1, m1, d1)
    days2 = date_to_days(y2, m2, d2)
    expected = abs(days2 - days1)
    out = run(x).strip()
    assert out.isdigit()
    got = int(out)
