def test_iterative_count(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    date1 = lines[0].strip()
    date2 = lines[1].strip()
    y1,m1,d1 = map(int, date1.split(':'))
    y2,m2,d2 = map(int, date2.split(':'))
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    def days_in_month(y, m):
        if m == 2:
            return 29 if is_leap(y) else 28
        if m in (1,3,5,7,8,10,12):
            return 31
        return 30
    def date_compare(y1,m1,d1, y2,m2,d2):
        if y1 != y2:
            return -1 if y1 < y2 else 1
        if m1 != m2:
            return -1 if m1 < m2 else 1
        if d1 != d2:
            return -1 if d1 < d2 else 1
        return 0
    cmp = date_compare(y1,m1,d1, y2,m2,d2)
    if cmp == 0:
        expected = 0
    else:
        if cmp > 0:
            sy,sm,sd = y2,m2,d2
            ey,em,ed = y1,m1,d1
        else:
            sy,sm,sd = y1,m1,d1
            ey,em,ed = y2,m2,d2
        count = 0
        while (sy,sm,sd) != (ey,em,ed):
            sd += 1
            dim = days_in_month(sy,sm)
            if sd > dim:
                sd = 1
                sm += 1
                if sm > 12:
                    sm = 1
                    sy += 1
            count += 1
        expected = count
    out_val = run(x).strip()
    got = int(out_val)
    assert got == expected

def test_datetime_oracle(run, x):
