def test_oracle(run, x):
    s, t = x.splitlines()
    from collections import Counter
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    cnt_s = Counter(s)
    cnt_t = Counter(t)
    if Counter(s) == Counter(t):
        expected = "array"
    elif is_subseq(t, s):
        expected = "automaton"
    elif all(cnt_s[c] >= cnt_t[c] for c in cnt_t):
        expected = "both"
    else:
