    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and ch == a[i]:
                i += 1
        return i == len(a)
    if is_subseq(t, s) and sorted(s) != sorted(t):
        output = run(x).strip()
        assert output == "automaton"

def test_counts_ge_not_subseq_not_anagram_implies_both(run, x):
    s, t = x.strip().splitlines()
    if s == t:
