    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and ch == a[i]:
                i += 1
        return i == len(a)
    if all(cs[c] >= ct[c] for c in ct) and not is_subseq(t, s) and sorted(s) != sorted(t):
        output = run(x).strip()
