def test_automaton_implies_subsequence(run, x):
    s, t = x.strip().splitlines()
    output = run(x).strip()
    if output == "automaton":
        def is_subseq(a, b):
            i = 0
            for ch in b:
                if i < len(a) and ch == a[i]:
                    i += 1
            return i == len(a)
        assert is_subseq(t, s)

def test_array_implies_anagram(run, x):
    s, t = x.strip().splitlines()
    output = run(x).strip()
