        assert sorted(s) == sorted(t)

def test_both_implies_conditions(run, x):
    s, t = x.strip().splitlines()
    output = run(x).strip()
    if output == "both":
        from collections import Counter
        cs = Counter(s)
        ct = Counter(t)
        def is_subseq(a, b):
            i = 0
            for ch in b:
                if i < len(a) and ch == a[i]:
                    i += 1
            return i == len(a)
        assert not is_subseq(t, s)
        assert all(cs[c] >= ct[c] for c in ct)
