    if output == "need tree":
        from collections import Counter
        cs = Counter(s)
        ct = Counter(t)
        assert any(cs[c] < ct[c] for c in ct)

def test_reference_acceptance(run, x):
    s, t = x.strip().splitlines()
    from collections import Counter
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and ch == a[i]:
                i += 1
        return i == len(a)
    automaton_possible = is_subseq(t, s)
    array_possible = sorted(s) == sorted(t)
    cs = Counter(s)
    ct = Counter(t)
    both_possible = (not automaton_possible) and (not array_possible) and all(cs[c] >= ct[c] for c in ct)
    if automaton_possible and array_possible:
        acceptable = {"automaton", "array"}
    elif array_possible:
        acceptable = {"array"}
    elif automaton_possible:
        acceptable = {"automaton"}
    elif both_possible:
        acceptable = {"both"}
    else:
        acceptable = {"need tree"}
    output = run(x).strip()
    assert output in acceptable

