def test_small_bruteforce(run, x):
    n = int(x.strip())
    if n > 4:
        return
    from collections import defaultdict
    def brute_force(n):
        nodes = {}
        children = defaultdict(list)
        id_counter = 0
        def get_id(s):
            nonlocal id_counter
            if s not in nodes:
                nodes[s] = id_counter
                id_counter += 1
            return nodes[s]
        stack = ['']
        visited = set()
        while stack:
            s = stack.pop()
            if s in visited:
                continue
            visited.add(s)
            pid = get_id(s)
            for ch in '()':
                s2 = s + ch
                if s2.count('(') <= n and s2.count(')') <= s2.count('('):
                    cid = get_id(s2)
                    children[pid].append(cid)
                    stack.append(s2)
        dp0 = {}
        dp1 = {}
        def dfs(u):
            base = 0
            for v in children[u]:
                dfs(v)
                base += dp0[v]
            dp1[u] = base
            best = base
            for v in children[u]:
                gain = 1 + dp1[v] + (base - dp0[v])
                if gain > best:
                    best = gain
            dp0[u] = best
        dfs(0)
        return dp0[0]
    expected = brute_force(n)
    MOD = 1000000007
    expected_mod = expected % MOD
    output = run(x)
    ans = int(output.strip())
    assert ans == expected_mod, f'brute force says {expected_mod}'


def test_small_dp(run, x):
    n = int(x.strip())
    if n > 8:
        return
    def compute_answer(n):
        MOD = 10**9+7
        f0 = [ [0]*(n+1-b) for b in range(n+1) ]
        f1 = [ [0]*(n+1-b) for b in range(n+1) ]
        for i in range(0, n+1):
            for b in range(0, n-i+1):
                children = []
                if i > 0:
                    children.append((b+1, i-1))
                if b > 0:
                    children.append((b-1, i))
                base = 0
                for (cb, ci) in children:
                    base += f0[cb][ci]
                f1[b][i] = base
                best = base
                for (cb, ci) in children:
                    gain = 1 + f1[cb][ci] + (base - f0[cb][ci])
                    if gain > best:
                        best = gain
                f0[b][i] = best
        ans = f0[0][n]
        return ans % MOD
    expected = compute_answer(n)
    output = run(x)
    ans = int(output.strip())
    assert ans == expected, f'DP says {expected}'


def test_dp_all(run, x):
    n = int(x.strip())
    def compute_answer(n):
        MOD = 10**9+7
        f0 = [ [0]*(n+1-b) for b in range(n+1) ]
        f1 = [ [0]*(n+1-b) for b in range(n+1) ]
        for i in range(0, n+1):
            for b in range(0, n-i+1):
                children = []
