def test_small_bruteforce(run, x_str):
    import heapq
    output = run(x_str)
    out_val = int(output.strip())
    n, x, y = map(int, x_str.strip().split())
    if n <= 1000:
        def bfs_cost(n, x, y):
            if n == 0:
                return 0
            max_node = 2 * n + 1000
            dist = {}
            heap = [(0, 0)]
            while heap:
                cost, node = heapq.heappop(heap)
                if node in dist and dist[node] < cost:
                    continue
                dist[node] = cost
                if node == n:
                    return cost
                if node + 1 <= max_node:
                    new_cost = cost + x
                    if node + 1 not in dist or new_cost < dist[node + 1]:
                        dist[node + 1] = new_cost
                        heapq.heappush(heap, (new_cost, node + 1))
                if node - 1 >= 0:
                    new_cost = cost + x
                    if node - 1 not in dist or new_cost < dist[node - 1]:
                        dist[node - 1] = new_cost
                        heapq.heappush(heap, (new_cost, node - 1))
                if node * 2 <= max_node:
                    new_cost = cost + y
                    if node * 2 not in dist or new_cost < dist[node * 2]:
                        dist[node * 2] = new_cost
                        heapq.heappush(heap, (new_cost, node * 2))
            return n * x
        expected = bfs_cost(n, x, y)
        assert out_val == expected

def test_n1(run, x_str):
    output = run(x_str)
    out_val = int(output.strip())
    n, x, y = map(int, x_str.strip().split())
