def test_dp(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    out = run(inp)
    ans = int(out.strip())
    # correct dp
    if n == 0:
        correct = 0
    else:
        dp = [0] * (n + 1)
        dp[1] = x_val
        for i in range(2, n + 1):
            dp[i] = dp[i-1] + x_val
            if i % 2 == 0:
                dp[i] = min(dp[i], dp[i//2] + y_val)
            else:
                dp[i] = min(dp[i], dp[(i+1)//2] + y_val + x_val)
        correct = dp[n]
    assert ans == correct

import heapq
def test_dijkstra(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    out = run(inp)
    ans = int(out.strip())
    limit = 2 * n + 100  # safe upper bound
    dist = {}
    pq = [(0, 0)]  # (cost, length)
    while pq:
        d, u = heapq.heappop(pq)
        if u in dist and dist[u] < d:
            continue
        if u == n:
            correct = d
            break
        # insert
        v = u + 1
        if v <= limit:
            nd = d + x_val
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
        # delete
        if u > 0:
            v = u - 1
            nd = d + x_val
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
        # duplicate
        v = 2 * u
        if v <= limit and u > 0:  # duplication requires at least one character
            nd = d + y_val
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    else:
        correct = float('inf')  # should not happen
    assert ans == correct

def test_upper_bound_nx(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    out = run(inp)
    ans = int(out.strip())
    assert ans <= n * x_val

def test_lower_bound_x(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    out = run(inp)
    ans = int(out.strip())
    assert ans >= x_val

def test_y_ge_nx(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    if y_val >= n * x_val:
        out = run(inp)
        ans = int(out.strip())
        assert ans == n * x_val

def test_output_format(run, inp):
    out = run(inp)
    s = out.strip()
    # must be a single integer
    int(s)  # raises ValueError if not integer
    # optionally check no extra whitespace
    assert out == s + '\n' or out == s

def test_even_upper_bound(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    if n % 2 == 0:
        out = run(inp)
        ans = int(out.strip())
        # compute dp for n//2
        half = n // 2
        if half == 0:
            dp_half = 0
        else:
            dp = [0] * (half + 1)
            dp[1] = x_val
            for i in range(2, half + 1):
                dp[i] = dp[i-1] + x_val
                if i % 2 == 0:
                    dp[i] = min(dp[i], dp[i//2] + y_val)
                else:
                    dp[i] = min(dp[i], dp[(i+1)//2] + y_val + x_val)
            dp_half = dp[half]
        assert ans <= dp_half + y_val

def test_odd_upper_bound(run, inp):
    n, x_val, y_val = map(int, inp.strip().split())
    if n % 2 == 1:
        out = run(inp)
