def test_output_integer(run, x):
    out = run(x)
    int(out.strip())

def test_output_positive(run, x):
    h = int(run(x).strip())
    assert h >= 1

def test_total_cubes_not_exceeded(run, x):
    n = int(x.strip())
    h = int(run(x).strip())
    total = h * (h + 1) * (h + 2) // 6
    assert total <= n

def test_next_level_impossible(run, x):
    n = int(x.strip())
    h = int(run(x).strip())
    total_next = (h + 1) * (h + 2) * (h + 3) // 6
    assert n < total_next

def test_matches_bruteforce(run, x):
    n = int(x.strip())
    h = int(run(x).strip())
    correct = 0
    while (correct + 1) * (correct + 2) * (correct + 3) // 6 <= n:
        correct += 1
    assert h == correct

def test_example_1(run, x):
    out = run(x)
    if x == "1\n":
        assert out == "1\n"

def test_example_25(run, x):
    out = run(x)
    if x == "25\n":
        assert out == "4\n"

def test_range_100_150(run, x):
    out = run(x)
    n = int(x.strip())
    if 100 <= n <= 150:
        h = int(out.strip())
        assert h in (7, 8)

def test_lower_bound_120(run, x):
    out = run(x)
    n = int(x.strip())
    if n >= 120:
        h = int(out.strip())
        assert h >= 8

def test_upper_bound_119(run, x):
    out = run(x)
    n = int(x.strip())
    if n < 120:
        h = int(out.strip())
        assert h <= 7

