def test_direct_formula(run, x):
    n,k = map(int, x.strip().split())
    D = [1,0,1,2,9]
    ans = 0
    for j in range(k+1):
        if j == 0:
            c = 1
        elif j == 1:
            c = n
        elif j == 2:
            c = n*(n-1)//2
        elif j == 3:
            c = n*(n-1)*(n-2)//6
        elif j == 4:
            c = n*(n-1)*(n-2)*(n-3)//24
        else:
            c = 0
        ans += c * D[j]
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == ans

def test_brute_force_small_n(run, x):
    n,k = map(int, x.strip().split())
    if n > 9:
        return
    import itertools
    count = 0
    for perm in itertools.permutations(range(1, n+1)):
        fixed = sum(1 for i in range(1, n+1) if perm[i-1] == i)
        if fixed >= n - k:
            count += 1
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == count

def test_positive(run, x):
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val > 0

def test_upper_bound_small_n(run, x):
    n,k = map(int, x.strip().split())
    if n > 12:
        return
    import math
    fact = math.factorial(n)
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val <= fact

def test_k1(run, x):
    n,k = map(int, x.strip().split())
    if k != 1:
        return
    out = run(x).strip()
    assert out == '1'

def test_k2(run, x):
    n,k = map(int, x.strip().split())
    if k != 2:
        return
    expected = 1 + n*(n-1)//2
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_k3(run, x):
    n,k = map(int, x.strip().split())
    if k != 3:
        return
    expected = 1 + n*(n-1)//2 + n*(n-1)*(n-2)//3
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_k4(run, x):
    n,k = map(int, x.strip().split())
    if k != 4:
        return
    expected = 1 + n*(n-1)//2 + 2 * n*(n-1)*(n-2)//6 + 9 * n*(n-1)*(n-2)*(n-3)//24
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

