tests_src:
def test_parse(run, x):
    out = run(x)
    s = out.strip()
    try:
        float(s)
    except ValueError:
        assert False

def test_positive(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    assert d > 0

def test_depth_gt_one(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    assert d > 1

def test_depth_gt_L_minus_H(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    assert d > l - h

def test_stem_gt_L(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    assert d + h > l

def test_upper_bound(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    upper = l * l / (2 * h)
    assert d <= upper * (1 + 1e-9) + 1e-9

def test_direct_comparison(run, x):
    h, l = map(int, x.strip().split())
    d_true = (l * l - h * h) / (2 * h)
    d = float(run(x).strip())
    if abs(d - d_true) > 1e-6 * max(1, abs(d_true)):
        assert False

def test_equation(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    residual = 2 * h * d + h * h - l * l
    tol = 1e-6 * max(1, 2 * h * d)
    if abs(residual) > tol:
        assert False

def test_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1
    s = lines[0].strip()
    try:
        float(s)
    except ValueError:
        assert False
    if any(c.isspace() for c in s):
        assert False
    assert s != ''

def test_not_too_large(run, x):
    d = float(run(x).strip())
    assert d < 1e13

