        total_max += 1.0 - prob_all_lt
    out = run(x)
    try:
        ans = float(out)
    except:
        assert False, "Output not a valid float"
    if not (ans >= total_min - 1e-9 and ans <= total_max + 1e-9):
        assert False, f"Expectation bounds violated: E[min]={total_min}, E[max]={total_max}, got {ans}"


