def test_output_format(run, x):
    output = run(x)
    assert output in {'YES\n', 'NO\n'}

def test_yes_implies_condition(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if output.strip() == 'YES':
        assert abs(a - b) <= 1 and a + b > 0

def test_condition_implies_yes(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if abs(a - b) <= 1 and a + b > 0:
        assert output.strip() == 'YES'

def test_zero_zero(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if a == 0 and b == 0:
        assert output.strip() == 'NO'

def test_sum_one(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if a + b == 1:
        assert output.strip() == 'YES'

def test_equal_small(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if a == b and 1 <= a <= 10:
        assert output.strip() == 'YES'

def test_diff_one_small(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if abs(a - b) == 1 and a + b <= 10:
        assert output.strip() == 'YES'

def test_large_equal(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if a == 100 and b == 100:
        assert output.strip() == 'YES'

def test_large_diff_one(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if (a, b) in {(99, 100), (100, 99)}:
        assert output.strip() == 'YES'

def test_false_case(run, x):
    a, b = map(int, x.strip().split())
    output = run(x)
    if (a, b) in {(0, 2), (2, 0)}:
        assert output.strip() == 'NO'

