def test_oracle(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0])
    events = []
    for line in lines[1:]:
        t, a = line.split()
        a = int(a)
        events.append((t, a))
    visitor_events = {}
    for t, a in events:
        if a not in visitor_events:
            visitor_events[a] = []
        visitor_events[a].append(t)
    valid = True
    for ev_list in visitor_events.values():
        for i in range(len(ev_list)-1):
            if ev_list[i] == ev_list[i+1]:
                valid = False
                break
        if not valid:
            break
    if not valid:
        return
    first_event_type = {}
    for t, a in events:
        if a not in first_event_type:
            first_event_type[a] = t
    initial = {a for a, t in first_event_type.items() if t == '-'}
    inside = set(initial)
    max_occ = len(inside)
    for t, a in events:
        if t == '+':
            inside.add(a)
        else:
            inside.remove(a)
        max_occ = max(max_occ, len(inside))
    output = run(x).strip()
    assert output == str(max_occ)

