    best = float('inf')
    for mask in range(1 << m):
        inside = set()
        for i in range(m):
            if mask & (1 << i):
                inside.add(visitors[i])
        consistent = True
        max_inside = len(inside)
        cur = set(inside)
        for op, num in events:
            r = int(num)
            if op == '+':
                if r in cur:
                    consistent = False
                    break
                cur.add(r)
            else:
                if r not in cur:
                    consistent = False
                    break
                cur.remove(r)
            if len(cur) > max_inside:
                max_inside = len(cur)
        if consistent and max_inside < best:
            best = max_inside
    correct = best
    ans = int(run(x).strip())
    assert ans == correct

def test_two_sets(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    cur_init = set()
    cur_log = set()
    for r, op in first.items():
        if op == '-':
            cur_init.add(r)
    ans_correct = len(cur_init)
    for op, num in events:
        r = int(num)
        if op == '+':
            cur_log.add(r)
            total = len(cur_log) + len(cur_init)
            if total > ans_correct:
                ans_correct = total
        else:
            total_before = len(cur_log) + len(cur_init)
            if total_before > ans_correct:
                ans_correct = total_before
            if r in cur_log:
                cur_log.remove(r)
            elif r in cur_init:
                cur_init.remove(r)
    ans = int(run(x).strip())
    assert ans == ans_correct

def test_lower_bound_first_minus(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    I = sum(1 for op in first.values() if op == '-')
    ans = int(run(x).strip())
    assert ans >= I

def test_lower_bound_max_delta(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    cur = 0
    max_delta = 0
    for op, _ in events:
        if op == '+':
            cur += 1
        else:
            cur -= 1
        if cur > max_delta:
            max_delta = cur
    ans = int(run(x).strip())
    assert ans >= max_delta

def test_upper_bound_distinct(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    distinct = set(int(num) for _, num in events)
    ans = int(run(x).strip())
    assert ans <= len(distinct)

def test_lower_bound_start_end(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    I = sum(1 for op in first.values() if op == '-')
    plus = sum(1 for op, _ in events if op == '+')
    minus = len(events) - plus
    delta_total = plus - minus
    lower = max(I, I + delta_total)
    ans = int(run(x).strip())
    assert ans >= lower

def test_upper_bound_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ans = int(run(x).strip())
    assert ans <= n

def test_state_simulation(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    state = {}
    for r, op in first.items():
        state[r] = 1 if op == '-' else 0
    cur = sum(state.values())
    max_inside = cur
    for op, num in events:
        r = int(num)
        if op == '+':
            state[r] = 1
            cur += 1
        else:
            state[r] = 0
            cur -= 1
        if cur > max_inside:
            max_inside = cur
    correct = max_inside
    ans = int(run(x).strip())
    assert ans == correct

def test_single_pass(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    seen = set()
    I = 0
    cur = 0
    max_delta = 0
    for op, num in events:
        r = int(num)
        if op == '-':
            if r not in seen:
                I += 1
        seen.add(r)
        if op == '+':
            cur += 1
        else:
            cur -= 1
        if cur > max_delta:
            max_delta = cur
    correct = I + max_delta
    ans = int(run(x).strip())
    assert ans == correct

