def test_full_oracle(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    assert len(out_lines) == t, f'Expected {t} output lines, got {len(out_lines)}'
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        # compute characters with at least one odd-length run
        odd_chars = set()
        j = 0
        while j < len(s):
            k = j
            while k < len(s) and s[k] == s[j]:
                k += 1
            if (k - j) % 2 == 1:
                odd_chars.add(s[j])
            j = k
        correct = ''.join(sorted(odd_chars))
        assert out_lines[i] == correct, f'Wrong answer: expected {correct!r}, got {out_lines[i]!r}'

def test_output_sorted(run, x):
    out_lines = run(x).strip().splitlines()
    for line in out_lines:
        for i in range(len(line)-1):
            assert line[i] < line[i+1], f'Output not sorted: {line!r}'

def test_output_subset(run, x):
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        out = out_lines[i]
        set_s = set(s)
        for c in out:
            assert c in set_s, f'Character {c!r} in output does not appear in input {s!r}'

def test_output_no_repeats(run, x):
    out_lines = run(x).strip().splitlines()
    for line in out_lines:
        assert len(set(line)) == len(line), f'Duplicate characters in output: {line!r}'

def test_odd_run_present(run, x):
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        out = out_lines[i]
        for c in out:
            found = False
            j = 0
            while j < len(s):
                if s[j] == c:
                    k = j
                    while k < len(s) and s[k] == c:
                        k += 1
                    if (k - j) % 2 == 1:
                        found = True
                        break
                    j = k
                else:
                    j += 1
            assert found, f'Character {c!r} in output but no odd-length run in {s!r}'

def test_even_run_absent(run, x):
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        out = out_lines[i]
        out_set = set(out)
        j = 0
        while j < len(s):
            c = s[j]
            if c not in out_set:
                k = j
                while k < len(s) and s[k] == c:
                    k += 1
                assert (k - j) % 2 == 0, f'Character {c!r} not in output but has odd run length {k-j} in {s!r}'
                j = k
            else:
                # skip the whole run of c
                k = j
                while k < len(s) and s[k] == c:
                    k += 1
                j = k

def test_output_length_match(run, x):
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        out = out_lines[i]
        odd_chars = set()
        j = 0
        while j < len(s):
            k = j
            while k < len(s) and s[k] == s[j]:
                k += 1
            if (k - j) % 2 == 1:
                odd_chars.add(s[j])
            j = k
        assert len(out) == len(odd_chars), f'Output length mismatch: expected {len(odd_chars)} characters, got {len(out)}'

def test_empty_output_implies_all_even(run, x):
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    out_lines = run(x).strip().splitlines()
    idx = 1
    for i in range(t):
        s = lines[idx].strip()
        idx += 1
        out = out_lines[i]
        if out == '':
            j = 0
            while j < len(s):
                k = j
                while k < len(s) and s[k] == s[j]:
                    k += 1
                assert (k - j) % 2 == 0, f'Empty output but character {s[j]!r} has odd run length {k-j} in {s!r}'
                j = k

