    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if n > 11:
        return
    from functools import lru_cache
    @lru_cache(None)
    def dfs(arr):
        if len(arr) == 1:
            return arr[0]
        best = 0
        m = len(arr)
        for i in range(m):
            left = (i-1) % m
            right = (i+1) % m
            new_val = arr[left] + arr[right]
