def test_format(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        assert line.startswith('<') and line.endswith('>'), f"Line does not have brackets: {line}"
        assert line.count('<') == 1 and line.count('>') == 1, f"Extra brackets in line: {line}"
        content = line[1:-1]
        assert '<' not in content and '>' not in content, f"Invalid characters in lexeme: {content}"


def test_no_quotes(run, x):
    output = run(x)
    assert '\"' not in output, "Output contains double quotes"


def test_at_least_one_lexeme(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) >= 1, "No lexemes output"


def test_length_sum(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    total_len = sum(len(line) - 2 for line in lines)
    assert total_len <= len(x), f"Sum of lexeme lengths {total_len} exceeds input length {len(x)}"


def test_lexeme_count(run, x):
    def count(s):
        cnt = 0
        i = 0
        n = len(s)
        while i < n:
            while i < n and s[i] == ' ':
                i += 1
            if i == n:
                break
            cnt += 1
            if s[i] == '\"':
                i += 1
                while i < n and s[i] != '\"':
                    i += 1
                if i == n:
                    break
                i += 1
            else:
                while i < n and s[i] != ' ':
                    i += 1
        return cnt
    expected = count(x)
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) == expected, f"Expected {expected} lexemes, got {len(lines)}"


def test_allowed_chars(run, x):
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,?! ")
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        content = line[1:-1]
        for ch in content:
            assert ch in allowed, f"Invalid character {ch} in lexeme {content}"


def test_full_oracle_small(run, x):
    if len(x) > 100:
        return
    def parse(s):
        lexemes = []
        i = 0
        n = len(s)
        while i < n:
            while i < n and s[i] == ' ':
                i += 1
            if i == n:
                break
            if s[i] == '\"':
                i += 1
                start = i
                while i < n and s[i] != '\"':
                    i += 1
                lexeme = s[start:i]
                lexemes.append(lexeme)
                i += 1
            else:
                start = i
                while i < n and s[i] != ' ':
                    i += 1
                lexeme = s[start:i]
                lexemes.append(lexeme)
        return lexemes
    expected = parse(x)
    output = run(x)
    lines = output.strip().split('\n')
    actual = [line[1:-1] for line in lines]
    assert actual == expected, f"Expected {expected}, got {actual}"


def test_no_stray_brackets(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        assert line.count('<') == 1 and line.count('>') == 1, f"Extra brackets in line: {line}"
        assert line[0] == '<' and line[-1] == '>', f"Brackets not at ends: {line}"


def test_lines_match_pattern(run, x):
    import re
    output = run(x)
    lines = output.strip().split('\n')
    pattern = re.compile(r'^<[^>]*>$')
    for line in lines:
        assert pattern.match(line), f"Line does not match pattern: {line}"


def test_no_backslash(run, x):
    output = run(x)
    assert '\\' not in output, "Output contains backslash"

