def test_exact_oracle(run, x):
    import sys
    sys.setrecursionlimit(10000)
    lines = x.strip().split()
    n = int(lines[0])
    a = list(map(int, lines[1:1+n]))
    from collections import Counter
    cnt = Counter(a)
    vals = list(cnt.keys())
    freqs = [cnt[v] for v in vals]
    best = 2
    def dfs(first_two):
        nonlocal best
        if len(first_two) == 2:
            seq = list(first_two)
            freq_copy = freqs.copy()
            idx0 = vals.index(seq[0])
            idx1 = vals.index(seq[1])
            freq_copy[idx0] -= 1
            freq_copy[idx1] -= 1
            if freq_copy[idx0] < 0 or freq_copy[idx1] < 0:
                return
            while True:
                nxt = seq[-1] + seq[-2]
                if nxt in cnt:
                    idx = vals.index(nxt)
                    if freq_copy[idx] > 0:
                        seq.append(nxt)
                        freq_copy[idx] -= 1
                    else:
                        break
                else:
                    break
            best = max(best, len(seq))
            return
        else:
            for i, v in enumerate(vals):
                if freqs[i] > 0:
                    freqs[i] -= 1
                    dfs(first_two + [v])
                    freqs[i] += 1
    dfs([])
    correct = best
    output = int(run(x).strip())
    assert output == correct, f"Expected {correct}, got {output}"


def test_output_range(run, x):
