            return
        if len(first_two) == 2:
            seq = list(first_two)
            freq_copy = freqs.copy()
            idx0 = vals.index(seq[0])
            idx1 = vals.index(seq[1])
            freq_copy[idx0] -= 1
            freq_copy[idx1] -= 1
            if freq_copy[idx0] < 0 or freq_copy[idx1] < 0:
                return
            while len(seq) < output:
                nxt = seq[-1] + seq[-2]
                if nxt in cnt:
                    idx = vals.index(nxt)
                    if freq_copy[idx] > 0:
                        seq.append(nxt)
                        freq_copy[idx] -= 1
                    else:
                        break
                else:
                    break
            if len(seq) >= output:
