def test_triple_lower_bound(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    a = list(map(int, lines[1:1+n]))
    from collections import Counter
    cnt = Counter(a)
    vals = list(cnt.keys())
    found = False
    for i, x in enumerate(vals):
        for j, y in enumerate(vals):
            if x == y:
                if cnt[x] >= 2:
                    if x + y in cnt:
                        if x + y == x:
                            if cnt[x] >= 3:
                                found = True
                        else:
                            if cnt[x + y] >= 1:
                                found = True
            else:
                if cnt[x] >= 1 and cnt[y] >= 1:
                    if x + y in cnt:
                        if x + y == x or x + y == y:
                            if cnt[x + y] >= 2:
                                found = True
                        else:
                            if cnt[x + y] >= 1:
                                found = True
            if found:
                break
        if found:
            break
    if found:
        output = int(run(x).strip())
        assert output >= 3, f"Triple exists, expected at least 3, got {output}"


def test_quadruple_lower_bound(run, x):
    lines = x.strip().split()
