    # oracle: maximal set condition
    pieces = []
    dots = []
    x_cells = []
    for i in range(n):
        for j in range(n):
            c = board[i][j]
            if c == 'o':
                pieces.append((i,j))
            elif c == '.':
                dots.append((i,j))
            elif c == 'x':
                x_cells.append((i,j))
    size = 2*n-1
    allowed = [[True]*size for _ in range(size)]
    for (pi,pj) in pieces:
        for (di,dj) in dots:
            dx = di - pi
            dy = dj - pj
            allowed[dx+n-1][dy+n-1] = False
    ok = True
    for (xi,xj) in x_cells:
        attacked = False
        for (pi,pj) in pieces:
            dx = xi - pi
            dy = xj - pj
            if allowed[dx+n-1][dy+n-1]:
                attacked = True
                break
        if not attacked:
            ok = False
            break
    expected_yes = ok
    output = run(x)
    lines_out = output.strip().split('\n')
    first = lines_out[0].strip()
    if expected_yes:
        assert first == 'YES', f'Expected YES, got {first}'
    else:
        assert first == 'NO', f'Expected NO, got {first}'

