        it = iter(data)
        t = int(next(it))
        out = []
        for _ in range(t):
            n = int(next(it)); k = int(next(it))
            l1 = int(next(it)); r1 = int(next(it))
            l2 = int(next(it)); r2 = int(next(it))
            base = max(0, min(r1, r2) - max(l1, l2))
            if base * n >= k:
                out.append('0')
                continue
            need = k - base * n
            L = min(l1, l2); R = max(r1, r2)
            union_len = R - L
            extra = union_len - base
            gap = max(0, max(l1, l2) - min(r1, r2))
            if extra == 0:
                ans = 2 * need
                out.append(str(ans))
                continue
            ans = 10**30
            for m in range(1, n + 1):
                if need <= m * extra:
                    p = (need + extra - 1) // extra
                    if p <= m:
                        cost = p * gap + need
                    else:
                        continue
                else:
                    cost = m * gap + 2 * need - m * extra
                if cost < ans:
                    ans = cost
            out.append(str(ans))
        return '\n'.join(out)
    expected = solve_correct(x).strip()
    got = run(x).strip()
    assert got == expected


