    it = iter(data)
    t = next(it)
    outputs = list(map(int, run(x).strip().split()))
    assert len(outputs) == t
    out_it = iter(outputs)
    for _ in range(t):
        n = next(it); k = next(it)
        l1 = next(it); r1 = next(it)
        l2 = next(it); r2 = next(it)
        base = max(0, min(r1, r2) - max(l1, l2))
        need = k - base * n
        if need > 0:
            ans = next(out_it)
            assert ans >= need
        else:
            next(out_it)


