    ans = out.rstrip('\n')
    if ans == '-':
        return
    i = 0
    for ch in ans:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            assert False, f"Output '{ans}' is not a subsequence of a='{a}'"
        i += 1

