def test_two_points_same_side_exact(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 2:
        return
    points = []
    for line in lines[1:]:
        if line.strip() == '':
            continue
        xi, yi = map(int, line.split())
        points.append((xi, yi))
    (x1, y1), (x2, y2) = points
    if y1 * y2 <= 0:
        return
    if y1 < 0:
        y1 = -y1
        y2 = -y2
    def f(cx):
        r1 = ((x1 - cx) ** 2 + y1 * y1) / (2 * y1)
        r2 = ((x2 - cx) ** 2 + y2 * y2) / (2 * y2)
        return max(r1, r2)
    lo, hi = -1e8, 1e8
    for _ in range(200):
        m1 = lo + (hi - lo) / 3
        m2 = hi - (hi - lo) / 3
        if f(m1) < f(m2):
            hi = m2
        else:
            lo = m1
    r_computed = f((lo + hi) / 2)
    out_str = run(x).strip()
    if out_str == '-1':
        out = -1.0
    else:
        out = float(out_str)
    if abs(out + 1) < 1e-9:
        assert False, f'Two points same side should not be -1'
    err = abs(out - r_computed) / max(1.0, r_computed)
    assert err <= 1e-6, f'Two points: expected {r_computed}, got {out}, err={err}'

def test_feasibility(run, x):
    import math
    out_str = run(x).strip()
    if out_str == '-1':
        out = -1.0
    else:
        out = float(out_str)
    if abs(out + 1) < 1e-9:
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    points = []
    for line in lines[1:]:
        if line.strip() == '':
            continue
        xi, yi = map(int, line.split())
        points.append((xi, yi))
    points_pos = [(x, abs(y)) for x, y in points]
    # feasibility check
    r = out
    intervals = []
    for x, y in points_pos:
        d = 2 * y * r - y * y
        if d < -1e-12:
            assert False, f'Radius {r} makes d negative for point ({x},{y})'
        if d < 0:
            d = 0.0
        sx = math.sqrt(d)
        left = x - sx
        right = x + sx
        intervals.append((left, right))
    left_max = max(l for l, r in intervals)
    right_min = min(r for l, r in intervals)
    if left_max > right_min + 1e-9:
        assert False, f'Radius {r} is not feasible'

