def test_not_exceed_total(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    total = b - a + 1
    assert val <= total

def test_k_eq_1(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if k != 1:
        return
    expected = b - a + 1
    assert val == expected

def test_single_point(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if a != b:
        return
    if a % k == 0:
        assert val == 1
    else:
        assert val == 0

def test_zero_interval(run, x):
    out = run(x).strip()
    try:
