def test_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert lines, "output empty"
    try:
        k = int(lines[0])
    except ValueError:
        assert False, "first line not integer"
    assert len(lines) == k + 1, f"expected {k+1} lines, got {len(lines)}"
    for i in range(1, k+1):
        parts = lines[i].split()
        assert len(parts) == 2, f"line {i} does not have two numbers"
        try:
            s = int(parts[0])
            t = int(parts[1])
        except ValueError:
            assert False, f"line {i} contains non-integer"


def test_sorted(run, x):
    out = run(x)
    lines = out.strip().split('\n')
