def test_t1_condition(run, x):
    lines_in = x.strip().split('\n')
    a = list(map(int, lines_in[1].split()))
    c1 = a.count(1)
    c2 = a.count(2)
    last = a[-1]
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        return
    k = int(lines_out[0])
    t1_pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
        if t == 1:
            t1_pairs.append((s, t))
    if last == 1:
        c_last = c1
        other = c2
    else:
        c_last = c2
        other = c1
