def test_brute_force_oracle(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    def parse_output(out):
        lines = out.strip().splitlines()
        if not lines:
            return 0, []
        k = int(lines[0])
        pairs = []
        for i in range(1, k+1):
            if i >= len(lines):
                break
            s, t = map(int, lines[i].split())
            pairs.append((s, t))
        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
    n, a = parse_input(x)
    valid = []
    for t in range(1, n+1):
        # first pass to get final set counts
        sets1 = sets2 = 0
        p1 = p2 = 0
        for serve in a:
            if serve == 1:
                p1 += 1
            else:
                p2 += 1
            if p1 == t or p2 == t:
                if p1 == t:
                    sets1 += 1
                else:
                    sets2 += 1
                p1 = p2 = 0
        if sets1 > sets2:
            winner = 1
            s = sets1
        elif sets2 > sets1:
            winner = 2
            s = sets2
        else:
            continue
        # second pass to verify match ends exactly at last point
        sets1 = sets2 = 0
        p1 = p2 = 0
        match_end = None
        for i, serve in enumerate(a, start=1):
            if serve == 1:
                p1 += 1
            else:
                p2 += 1
            if p1 == t or p2 == t:
                if p1 == t:
                    sets1 += 1
                else:
                    sets2 += 1
                if winner == 1 and sets1 == s and sets2 < s and match_end is None:
                    match_end = i
                elif winner == 2 and sets2 == s and sets1 < s and match_end is None:
                    match_end = i
                p1 = p2 = 0
        if match_end is not None and match_end == len(a) and p1 == 0 and p2 == 0:
            valid.append((s, t))
    valid.sort(key=lambda p: (p[0], p[1]))
    out = run(x)
    k_out, pairs_out = parse_output(out)
    assert k_out == len(valid), 'wrong number of pairs'
    assert pairs_out == valid, 'pairs do not match expected'


def test_output_sorted_and_positive(run, x):
    def parse_output(out):
        lines = out.strip().splitlines()
        if not lines:
            return 0, []
        k = int(lines[0])
        pairs = []
        for i in range(1, k+1):
            if i >= len(lines):
                break
            s, t = map(int, lines[i].split())
            pairs.append((s, t))
        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
    out = run(x)
    k, pairs = parse_output(out)
    for s, t in pairs:
        assert s >= 1 and t >= 1, 's or t not positive'
    for i in range(len(pairs)-1):
        s1, t1 = pairs[i]
