            pairs.append((s, t))
        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
    n, a = parse_input(x)
    out = run(x)
    k, pairs = parse_output(out)
    for s, t in pairs:
        sets1 = sets2 = 0
        p1 = p2 = 0
        match_end = None
        for i, serve in enumerate(a, start=1):
            if serve == 1:
                p1 += 1
            else:
                p2 += 1
            if p1 == t or p2 == t:
                if p1 == t:
                    sets1 += 1
                else:
                    sets2 += 1
                if sets1 == s and sets2 < s and match_end is None:
                    match_end = i
                elif sets2 == s and sets1 < s and match_end is None:
                    match_end = i
                p1 = p2 = 0
        if match_end is None or match_end != len(a) or p1 != 0 or p2 != 0:
            assert False, f'Pair ({s},{t}) invalid: match did not end exactly at last point'
        winner = 1 if sets1 > sets2 else 2
        assert winner == a[-1], f'Pair ({s},{t}): winner does not match last point winner'


