def test_no_crash(run, x):
    try:
        run(x)
    except:
        assert False, "program crashed"

def test_output_integer(run, x):
    out = run(x)
    out = out.strip()
    try:
        int(out)
    except:
        assert False, "output is not an integer"

def test_output_range(run, x):
    out = run(x)
    out = out.strip()
    ans = int(out)
    lines = x.split('\n')
    n = int(lines[0].strip())
    assert 1 <= ans <= n, f"ans={ans} not in [1,{n}]"

def test_ge_max_counts(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.split('\n')
    n = int(lines[0].strip())
    s = lines[1] if len(lines) > 1 else ''
    if len(s) != n or any(c not in 'UR' for c in s):
        return
    countU = s.count('U')
    countR = s.count('R')
    assert ans >= max(countU, countR), f"ans={ans} < max(countU,countR)={max(countU,countR)}"

def test_all_same(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.split('\n')
    n = int(lines[0].strip())
    s = lines[1] if len(lines) > 1 else ''
    if len(s) != n or any(c not in 'UR' for c in s):
        return
    if all(c == s[0] for c in s):
        assert ans == n, f"all same, ans={ans} != n={n}"

def test_alternating(run, x):
    import math
    out = run(x)
    ans = int(out.strip())
    lines = x.split('\n')
    n = int(lines[0].strip())
    s = lines[1] if len(lines) > 1 else ''
    if len(s) != n or any(c not in 'UR' for c in s):
        return
    is_alt = all(s[i] != s[i+1] for i in range(n-1))
    if is_alt:
        expected = (n + 1) // 2
        assert ans == expected, f"alternating, ans={ans} != ceil(n/2)={expected}"

def test_examples(run, x):
    out = run(x)
    if x == "5\nRUURU\n":
        assert out.strip() == "3", f"example 1: expected 3, got {out.strip()}"
    elif x == "17\nUUURRRRRUUURURUUU\n":
        assert out.strip() == "13", f"example 2: expected 13, got {out.strip()}"

def test_stack_oracle(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.split('\n')
    n = int(lines[0].strip())
    s = lines[1] if len(lines) > 1 else ''
    if len(s) != n or any(c not in 'UR' for c in s):
        return
    stack = []
    for c in s:
        if stack and stack[-1] in 'UR' and c in 'UR' and stack[-1] != c:
            stack.pop()
            stack.append('D')
        else:
            stack.append(c)
    expected = len(stack)
    assert ans == expected, f"oracle expected {expected}, got {ans}"

def test_output_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), "output does not end with newline"

def test_output_no_extra_whitespace(run, x):
    out = run(x)
    ans_str = out.strip()
    if not (out == ans_str or out == ans_str + '\n'):
        assert False, "output contains extra whitespace"

