def test_backward_suffix_length(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) != 2:
        return
    try:
        n = int(first[0])
        c = int(first[1])
    except:
        return
    if not (1 <= n <= 100000 and 1 <= c <= 10**9):
        return
    second = lines[1].split()
    if len(second) != n:
        return
    try:
        t = list(map(int, second))
    except:
        return
    if not (1 <= t[0] and all(t[i-1] < t[i] for i in range(1, n)) and t[-1] <= 10**9):
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    L = 1
    i = n-1
    while i > 0 and t[i] - t[i-1] <= c:
        L += 1
        i -= 1
    assert ans == L, f"Backward suffix length is {L}, got {ans}"

def test_last_reset_index(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) != 2:
        return
    try:
        n = int(first[0])
        c = int(first[1])
    except:
        return
    if not (1 <= n <= 100000 and 1 <= c <= 10**9):
        return
    second = lines[1].split()
    if len(second) != n:
        return
    try:
        t = list(map(int, second))
    except:
        return
    if not (1 <= t[0] and all(t[i-1] < t[i] for i in range(1, n)) and t[-1] <= 10**9):
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    last_reset = 0
    for j in range(1, n):
        if t[j] - t[j-1] > c:
            last_reset = j
    expected = n - last_reset
    assert ans == expected, f"Last reset index gives {expected}, got {ans}"

