def test_periodic_210(run, x):
    n = int(x.strip())
    good = [0]*210
    cnt = 0
    for i in range(1, 210):
        if i % 2 != 0 and i % 3 != 0 and i % 5 != 0 and i % 7 != 0:
            cnt += 1
        good[i] = cnt
    q, r = divmod(n, 210)
    expected = q * 48 + good[r]
    output = int(run(x).strip())
    assert output == expected

def test_direct_brute_force(run, x):
    n = int(x.strip())
    if n > 5000:
        return
    cnt = 0
    for i in range(1, n+1):
        ok = True
        for d in range(2, 11):
            if i % d == 0:
                ok = False
                break
        if ok:
            cnt += 1
    output = int(run(x).strip())
    assert output == cnt

def test_inclusion_exclusion_small(run, x):
    n = int(x.strip())
    if n > 1000:
        return
    primes = [2,3,5,7]
    total = 0
    for mask in range(1, 16):
        prod = 1
        bits = 0
        for i in range(4):
            if mask >> i & 1:
                prod *= primes[i]
                bits += 1
        cnt = n // prod
        if bits % 2 == 1:
            total += cnt
        else:
            total -= cnt
    expected = n - total
    output = int(run(x).strip())
    assert output == expected

