def test_bruteforce_small(run, x):
    n = int(x.strip())
    if n > 4:
        return
    import itertools
    from functools import lru_cache
    size = n
    total = size * size
    neighbors = [[] for _ in range(total)]
    for i in range(size):
        for j in range(size):
            idx = i * size + j
            if i > 0:
                neighbors[idx].append((i - 1) * size + j)
            if i < size - 1:
                neighbors[idx].append((i + 1) * size + j)
            if j > 0:
                neighbors[idx].append(i * size + (j - 1))
            if j < size - 1:
                neighbors[idx].append(i * size + (j + 1))
    @lru_cache(maxsize=None)
    def win(mask):
        if mask == 0:
            return False
        v = 0
        m = mask
        while m:
            if m & 1:
                new_mask = mask & ~(1 << v)
                for nb in neighbors[v]:
                    new_mask &= ~(1 << nb)
                if not win(new_mask):
                    return True
            v += 1
            m >>= 1
        return False
    initial = (1 << total) - 1
    correct = 1 if win(initial) else 2
    out = run(x)
    assert int(out.strip()) == correct, f"For n={n}, correct answer is {correct}, got {out.strip()}"

