def test_output_at_least_monochrome_path(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    s = lines[1].strip()
    adj = [[] for _ in range(n+1)]
    for i in range(m):
        u, v = map(int, lines[2+i].split())
        adj[u].append(v)
    import sys
    sys.setrecursionlimit(1000000)
    visited = [0] * (n+1)
    has_cycle = False
    def dfs_cycle(u):
        nonlocal has_cycle
        if has_cycle:
            return
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 0:
                dfs_cycle(v)
            elif visited[v] == 1:
                has_cycle = True
                return
        visited[u] = 2
    for i in range(1, n+1):
        if visited[i] == 0:
            dfs_cycle(i)
        if has_cycle:
            break
    if has_cycle:
        return
    rev_adj = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in adj[u]:
            rev_adj[v].append(u)
    indeg = [0] * (n+1)
    for u in range(1, n+1):
        for v in adj[u]:
            indeg[v] += 1
    from collections import deque
    q = deque([i for i in range(1, n+1) if indeg[i] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    dp_mono = [0] * (n+1)
    for u in topo:
        best = 0
        for v in rev_adj[u]:
            if s[v-1] == s[u-1]:
                if dp_mono[v] > best:
                    best = dp_mono[v]
        dp_mono[u] = best + 1
    max_mono = max(dp_mono[1:]) if n > 0 else 0
    out = run(x).strip()
    if out != "-1":
        val = int(out)
