def test_output_format(run, x):
    out = run(x)
    tokens = out.split()
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    assert len(tokens) == k, f"Expected {k} integers, got {len(tokens)}"
    for token in tokens:
        int(token)

def test_non_negative(run, x):
    out = run(x)
    for token in out.split():
        val = int(token)
        assert val >= 0, f"Negative output {val}"

def test_upper_bound_total(run, x):
    out = run(x)
    vals = list(map(int, out.split()))
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    grid = [line.rstrip() for line in lines[1:1+n]]
    total = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '*':
                        total += 1
    for v in vals:
        assert v <= total, f"Output {v} exceeds total pictures {total}"

def test_lower_bound_cell(run, x):
    out = run(x)
    vals = list(map(int, out.split()))
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    grid = [line.rstrip() for line in lines[1:1+n]]
    queries = []
    for i in range(k):
        line = lines[1+n+i]
        xq, yq = map(int, line.split())
        queries.append((xq-1, yq-1))
    for (qx, qy), v in zip(queries, vals):
        cnt = 0
        for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
            ni, nj = qx+di, qy+dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '*':
                cnt += 1
        assert v >= cnt, f"Output {v} less than adjacent pictures {cnt} for cell ({qx},{qy})"

def test_component_consistency(run, x):
    out = run(x)
    vals = list(map(int, out.split()))
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    grid = [line.rstrip() for line in lines[1:1+n]]
    queries = []
    for i in range(k):
        line = lines[1+n+i]
        xq, yq = map(int, line.split())
        queries.append((xq-1, yq-1))
    from collections import deque
    visited = [[False]*m for _ in range(n)]
    comp_id = [[-1]*m for _ in range(n)]
    comp_counter = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                q = deque()
                q.append((i,j))
                visited[i][j] = True
                comp_id[i][j] = comp_counter
                while q:
                    ci, cj = q.popleft()
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and not visited[ni][nj]:
                            visited[ni][nj] = True
                            comp_id[ni][nj] = comp_counter
                            q.append((ni,nj))
                comp_counter += 1
    comp_value = {}
    for idx, (qx, qy) in enumerate(queries):
        cid = comp_id[qx][qy]
        if cid not in comp_value:
            comp_value[cid] = vals[idx]
        else:
            assert vals[idx] == comp_value[cid], f"Queries in same component have different outputs: {vals[idx]} vs {comp_value[cid]}"

def test_isolated_cell(run, x):
    out = run(x)
    vals = list(map(int, out.split()))
    lines = x.strip().split('\n')
    first = lines[0].split()
