    for i in range(k):
        line = lines[1+n+i]
        xq, yq = map(int, line.split())
        queries.append((xq-1, yq-1))
    from collections import deque
    visited = [[False]*m for _ in range(n)]
    comp_id = [[-1]*m for _ in range(n)]
    comp_value = {}
    comp_counter = 0
    for i in range(n):
