                q.append((i,j))
                visited[i][j] = True
                cells = []
                while q:
                    ci, cj = q.popleft()
                    cells.append((ci,cj))
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and not visited[ni][nj]:
