    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    grid = [line.rstrip() for line in lines[1:1+n]]
    from collections import deque
    visited = [[False]*m for _ in range(n)]
    components = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                components += 1
                if components > 1:
                    return
                q = deque()
                q.append((i,j))
                visited[i][j] = True
                while q:
                    ci, cj = q.popleft()
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and not visited[ni][nj]:
                            visited[ni][nj] = True
                            q.append((ni,nj))
    if len(vals) > 0:
        first_val = vals[0]
        for v in vals[1:]:
            assert v == first_val, f"All outputs should be equal in single component, but got {vals}"

