def test_bruteforce(run, x):
    s, t = x.strip().splitlines()
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and ch == a[i]:
                i += 1
        return i == len(a)
    expected = 0
    for i in range(len(t)+1):
        left = t[:i]
        right = t[i:]
        if is_subseq(s, left) and is_subseq(s, right):
            expected += 1
    got = int(run(x).strip())
    assert got == expected

def test_leftmost_rightmost(run, x):
    s, t = x.strip().splitlines()
    pos = 0
    left_end = -1
    for i, ch in enumerate(t):
        if pos < len(s) and ch == s[pos]:
            pos += 1
            if pos == len(s):
                left_end = i
                break
    if left_end == -1:
        expected = 0
    else:
        pos = len(s)-1
        right_start = -1
        for i in range(len(t)-1, -1, -1):
            if pos >= 0 and t[i] == s[pos]:
                pos -= 1
                if pos == -1:
                    right_start = i
                    break
        expected = max(0, right_start - left_end)
    got = int(run(x).strip())
    assert got == expected

def test_single_char_rule(run, x):
    s, t = x.strip().splitlines()
    if len(s) != 1:
        return
    ch = s[0]
    first = None
    last = None
    for i, c in enumerate(t):
        if c == ch:
            if first is None:
                first = i
            last = i
    if first is None:
        expected = 0
    else:
        expected = max(0, last - first)
    got = int(run(x).strip())
    assert got == expected

def test_zero_if_no_subsequence(run, x):
    s, t = x.strip().splitlines()
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and ch == a[i]:
                i += 1
        return i == len(a)
    if not is_subseq(s, t):
        got = int(run(x).strip())
        assert got == 0

def test_zero_if_t_equals_s(run, x):
    s, t = x.strip().splitlines()
    if t == s:
        got = int(run(x).strip())
        assert got == 0

def test_upper_bound(run, x):
    s, t = x.strip().splitlines()
    got = int(run(x).strip())
    assert got <= len(t) + 1

def test_nonnegative(run, x):
    got = int(run(x).strip())
    assert got >= 0

def test_examples(run, x):
    if x == "aba\nbaobababbah\n":
        output = run(x)
        assert output == "2\n"
    elif x == "mars\nsunvenusearthmarsjupitersaturnuranusneptune\n":
        output = run(x)
        assert output == "0\n"

def test_parses_as_int(run, x):
    output = run(x)
    int(output.strip())

def test_no_extra_spaces(run, x):
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == 1
    line = lines[0]
    assert line.strip() == line
    assert line.isdigit()

