def test_exact_output(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    day_fall = [0]*(n+1)
    for day, size in enumerate(a, start=1):
        day_fall[size] = day
    day_place = [0]*(n+1)
    day_place[n] = day_fall[n]
    for s in range(n-1, 0, -1):
        day_place[s] = max(day_fall[s], day_place[s+1])
    expected = []
    for day in range(1, n+1):
        sizes = [s for s in range(1, n+1) if day_place[s] == day]
        sizes.sort(reverse=True)
        line = ' '.join(str(s) for s in sizes) if sizes else ''
        expected.append(line)
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    lines = [line.rstrip() for line in lines]
    if len(lines) != n:
        assert False, f"line count mismatch: expected {n}, got {len(lines)}"
    for i in range(n):
        if lines[i] != expected[i]:
            assert False, f"line {i+1} mismatch: expected '{expected[i]}', got '{lines[i]}'"


def test_line_count(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    assert len(lines) == n, f"expected {n} lines, got {len(lines)}"


def test_decreasing_per_line(run, x):
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    for idx, line in enumerate(lines):
        line = line.rstrip()
        if line:
            nums = list(map(int, line.split()))
            for i in range(len(nums)-1):
                if nums[i] <= nums[i+1]:
                    assert False, f"line {idx+1} not decreasing: {nums}"


def test_all_numbers_present(run, x):
    lines_in = x.strip().split('\n')
