    for line in lines:
        line = line.rstrip()
        if line:
            all_nums.extend(map(int, line.split()))
    if set(all_nums) != set(range(1, n+1)):
        assert False, f"missing or extra numbers"
    if len(all_nums) != n:
        assert False, f"duplicate or missing numbers: expected {n}, got {len(all_nums)}"


def test_concatenated_sequence(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    seq = []
    for line in lines:
        line = line.rstrip()
        if line:
            seq.extend(map(int, line.split()))
    expected = list(range(n, 0, -1))
    if seq != expected:
        assert False, f"concatenated sequence mismatch: expected {expected}, got {seq}"


def test_fall_before_placement(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    day_fall = [0]*(n+1)
    for day, size in enumerate(a, start=1):
        day_fall[size] = day
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    day_place = [0]*(n+1)
