                    assert False, f"line {idx+1} not consecutive decreasing: {nums}"


def test_recurrence(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    day_fall = [0]*(n+1)
    for day, size in enumerate(a, start=1):
