    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    day_place = [0]*(n+1)
    for day_idx, line in enumerate(lines, start=1):
        line = line.rstrip()
        if line:
            for size in map(int, line.split()):
                day_place[size] = day_idx
    if day_place[n] != day_fall[n]:
        assert False, f"size {n} placement day {day_place[n]} != fall day {day_fall[n]}"
    for s in range(n-1, 0, -1):
