def test_oracle_small(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n > 10:
        return
    sizes = list(map(int, lines[1].split()))
    if len(sizes) != n or set(sizes) != set(range(1, n+1)):
        return
    waiting = set()
    expected = n
    expected_lines = []
    for snack in sizes:
        waiting.add(snack)
        line_tokens = []
        while expected in waiting:
            line_tokens.append(str(expected))
            waiting.remove(expected)
            expected -= 1
        expected_lines.append(' '.join(line_tokens))
    out = run(x)
    submitted_lines = out.splitlines()
    while len(submitted_lines) < n:
        submitted_lines.append('')
    submitted_lines = submitted_lines[:n]
    norm_submitted = []
    for line in submitted_lines:
        tokens = line.split()
        norm_submitted.append(' '.join(tokens))
    norm_expected = []
    for line in expected_lines:
        tokens = line.split()
        norm_expected.append(' '.join(tokens))
    assert norm_submitted == norm_expected

