def test_profit_nonnegative(run, x):
    out = run(x)
    s = out.strip()
    try:
        profit = int(s)
    except ValueError:
        assert False
    assert profit >= 0

def test_output_integer(run, x):
    out = run(x)
    assert out.strip().isdigit()

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped.isdigit()
    assert out == stripped + '\n' or out == stripped

def test_small_dp(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if not lines:
        return
    N = int(lines[0].strip())
    if N > 30:
        return
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    INF_NEG = -10**18
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(N):
        p = prices[i]
        for k in range(N + 1):
            cur = dp[i][k]
            if cur == INF_NEG:
                continue
            if dp[i + 1][k] < cur:
                dp[i + 1][k] = cur
            if k < N:
                buy = cur - p
                if dp[i + 1][k + 1] < buy:
                    dp[i + 1][k + 1] = buy
            if k > 0:
                sell = cur + p
                if dp[i + 1][k - 1] < sell:
                    dp[i + 1][k - 1] = sell
    optimal = dp[N][0]
    profit = int(out.strip())
    assert profit == optimal

def test_monotonic_increasing(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    if all(prices[i] <= prices[i + 1] for i in range(N - 1)):
        profit = int(out.strip())
        assert profit == prices[-1] - prices[0]

def test_monotonic_decreasing(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    if all(prices[i] >= prices[i + 1] for i in range(N - 1)):
        profit = int(out.strip())
        assert profit == 0

def test_all_equal(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    if all(p == prices[0] for p in prices):
        profit = int(out.strip())
        assert profit == 0

def test_two_days(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    if N != 2:
        return
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < 2:
        return
    prices = prices[:2]
    profit = int(out.strip())
    expected = max(0, prices[1] - prices[0])
    assert profit == expected

def test_upper_bound(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    min_so_far = prices[0]
    bound = 0
    for i in range(1, N):
        bound += max(0, prices[i] - min_so_far)
        min_so_far = min(min_so_far, prices[i])
    profit = int(out.strip())
    assert profit <= bound

def test_examples(run, x):
    example1 = "9\n10 5 4 7 9 12 6 2 10\n"
    example2 = "20\n3 1 4 1 5 9 2 6 5 3 5 8 9 7 9 3 2 3 8 4\n"
    out = run(x)
    if x == example1:
        assert out.strip() == "20"
    elif x == example2:
        assert out.strip() == "41"

