def test_correct_expansion(run, x):
    def expand(short):
        if '::' in short:
            left, right = short.split('::', 1)
            left_parts = left.split(':') if left else []
            right_parts = right.split(':') if right else []
            num_missing = 8 - len(left_parts) - len(right_parts)
            blocks = [p.zfill(4) for p in left_parts] + ['0000'] * num_missing + [p.zfill(4) for p in right_parts]
            return ':'.join(blocks)
        else:
            parts = short.split(':')
            blocks = [p.zfill(4) for p in parts]
            return ':'.join(blocks)
    lines = x.strip().splitlines()
    n = int(lines[0])
    shorts = lines[1:1+n]
    output = run(x).strip()
    out_lines = output.splitlines()
    assert len(out_lines) == n
    for i in range(n):
        assert out_lines[i] == expand(shorts[i])

def test_output_length(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    output = run(x).strip()
    out_lines = output.splitlines()
    assert len(out_lines) == n
    for line in out_lines:
        assert len(line) == 39

def test_block_count(run, x):
    output = run(x).strip()
    for line in output.splitlines():
        assert len(line.split(':')) == 8

def test_block_format(run, x):
    import re
    pattern = re.compile('^[0-9a-f]{4}$')
    output = run(x).strip()
    for line in output.splitlines():
        for block in line.split(':'):
            assert pattern.match(block) is not None

def test_no_double_colon(run, x):
    output = run(x).strip()
    for line in output.splitlines():
        assert '::' not in line

def test_hex_chars(run, x):
    allowed = set('0123456789abcdef:')
    output = run(x).strip()
    for line in output.splitlines():
        for ch in line:
            assert ch in allowed

def test_non_empty_blocks_match(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    shorts = lines[1:1+n]
    output = run(x).strip()
    out_lines = output.splitlines()
    for i in range(n):
        short = shorts[i]
        if '::' not in short:
            in_blocks = short.split(':')
            out_blocks = out_lines[i].split(':')
            assert len(in_blocks) == 8
            for j in range(8):
                stripped = out_blocks[j].lstrip('0')
                if stripped == '':
                    stripped = '0'
                assert stripped == in_blocks[j]

def test_shortening_possible(run, x):
    def all_shortenings(full):
        blocks = full.split(':')
        short_blocks = [b.lstrip('0') if b != '0000' else '0' for b in blocks]
        possible = set()
        possible.add(':'.join(short_blocks))
        for start in range(8):
            for end in range(start, 8):
                if all(short_blocks[j] == '0' for j in range(start, end+1)):
                    left = ':'.join(short_blocks[:start])
                    right = ':'.join(short_blocks[end+1:])
                    if left and right:
                        short = left + '::' + right
                    elif left:
                        short = left + '::'
                    elif right:
                        short = '::' + right
                    else:
                        short = '::'
                    possible.add(short)
        return possible
    lines = x.strip().splitlines()
    n = int(lines[0])
    shorts = lines[1:1+n]
    output = run(x).strip()
    out_lines = output.splitlines()
    for i in range(n):
        short = shorts[i]
        full = out_lines[i]
        assert short in all_shortenings(full)

def test_colon_count(run, x):
    output = run(x).strip()
    for line in output.splitlines():
        assert line.count(':') == 7

def test_lowercase(run, x):
    output = run(x).strip()
    for line in output.splitlines():
        assert line == line.lower()

