def test_full_correct(run, x):
    def correct_answer(n, a):
        a_sorted = sorted(a)
        for i in range(len(a_sorted)-2):
            if a_sorted[i] == a_sorted[i+2]:
                return "cslnb"
        dup_count = 0
        dup_value = -1
        for i in range(len(a_sorted)-1):
            if a_sorted[i] == a_sorted[i+1]:
                dup_count += 1
                dup_value = a_sorted[i]
        if dup_count > 1:
            return "cslnb"
        if dup_count == 1:
            if dup_value == 0:
                return "cslnb"
            if (dup_value - 1) in a_sorted:
                return "cslnb"
        total = sum(a)
        min_sum = n*(n-1)//2
        moves = total - min_sum
        if moves % 2 == 1:
            return "sjfnb"
        else:
            return "cslnb"
