def test_oracle(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    if H > 8 or W > 8:
        return
    from collections import Counter
    rows = grid
    row_cnt = [Counter(r) for r in rows]
    def can_pal(cnt):
        odd = sum(1 for v in cnt.values() if v % 2 == 1)
        return odd <= 1
    row_used = [False]*H
    row_assign = [-1]*H
    def backtrack_rows(i):
        if i >= (H+1)//2:
            col_used = [False]*W
            col_assign = [-1]*W
            def backtrack_cols(j):
                if j >= (W+1)//2:
                    return True
                unused = [c for c in range(W) if not col_used[c]]
                if j == W-1-j:
                    for c in unused:
                        ok = True
                        for i2 in range(H):
                            if rows[row_assign[i2]][c] != rows[row_assign[H-1-i2]][c]:
                                ok = False
                                break
                        if not ok:
                            continue
                        col_used[c] = True
                        col_assign[j] = c
                        if backtrack_cols(j+1):
                            return True
                        col_used[c] = False
                    return False
                else:
                    for c1 in unused:
                        col_used[c1] = True
                        for c2 in unused:
                            if col_used[c2]:
                                continue
                            ok = True
                            for i2 in range(H):
                                if rows[row_assign[i2]][c1] != rows[row_assign[H-1-i2]][c2] or rows[row_assign[i2]][c2] != rows[row_assign[H-1-i2]][c1]:
                                    ok = False
                                    break
                            if not ok:
                                continue
                            col_used[c2] = True
                            col_assign[j] = c1
                            col_assign[W-1-j] = c2
                            if backtrack_cols(j+1):
                                return True
                            col_used[c2] = False
                        col_used[c1] = False
                    return False
            return backtrack_cols(0)
        else:
            if i == H-1-i:
                for r in range(H):
                    if not row_used[r]:
                        if not can_pal(row_cnt[r]):
                            continue
                        row_used[r] = True
                        row_assign[i] = r
                        if backtrack_rows(i+1):
                            return True
                        row_used[r] = False
                return False
            else:
                unused = [r for r in range(H) if not row_used[r]]
                for r1 in unused:
                    row_used[r1] = True
                    for r2 in unused:
                        if row_used[r2]:
                            continue
                        if row_cnt[r1] != row_cnt[r2]:
                            continue
                        row_used[r2] = True
                        row_assign[i] = r1
                        row_assign[H-1-i] = r2
                        if backtrack_rows(i+1):
                            return True
                        row_used[r2] = False
                    row_used[r1] = False
                return False
    possible = backtrack_rows(0)
    expected = "YES\n" if possible else "NO\n"
    output = run(x)
    assert output == expected, f"Oracle says {expected.strip()} but got {output.strip()}"


