def test_oracle(run, x):
    import math
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    output = run(x).strip()
    if s > n:
        correct = -1
    elif s == n:
        correct = n + 1
    else:
        l = n - s
        sqrt_n = int(math.isqrt(n)) + 1
        ans = None
        for b in range(2, sqrt_n + 1):
            t = 0
            u = n
            while u:
                t += u % b
                u //= b
            if t == s:
                ans = b
                break
        for a in range(1, sqrt_n + 1):
            if l % a != 0:
                continue
            b = l // a + 1
            if b <= sqrt_n:
                continue
            if b < 2:
                continue
            if a >= b:
                continue
            c = s - a
            if c < 0 or c >= b:
                continue
            if n != a * b + c:
                continue
            if ans is None or b < ans:
                ans = b
        correct = -1 if ans is None else ans
    try:
        out_val = int(output)
    except ValueError:
        assert False, "Output is not an integer"
    assert out_val == correct, f"Oracle mismatch: got {out_val}, expected {correct}"


