def test_possible(run, x):
    s = x.strip()
    def correct_suffixes(s):
        n = len(s)
        ok2 = [False]*(n+1)
        ok3 = [False]*(n+1)
        if n >= 2:
            ok2[n-2] = True
        if n >= 3:
            ok3[n-3] = True
        for i in range(n-4, -1, -1):
            if i+2 <= n:
                if i+2 == n:
                    ok2[i] = True
                else:
                    if ok3[i+2]:
                        ok2[i] = True
                    if ok2[i+2] and s[i:i+2] != s[i+2:i+4]:
