def test_full_combinatorial(run, x):
    out = run(x)
    val = int(out.strip())
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    MOD = 1000000007
    from collections import Counter
    prime_exp = Counter()
    for num in a:
        x = num
        p = 2
        while p * p <= x:
            while x % p == 0:
                prime_exp[p] += 1
                x //= p
            p += 1 if p == 2 else 2
        if x > 1:
            prime_exp[x] += 1
    if not prime_exp:
        ans = 1
    else:
        max_needed = max(e + n - 1 for e in prime_exp.values())
        limit = max_needed + 10
        fact = [1] * (limit + 1)
        for i in range(1, limit + 1):
            fact[i] = fact[i-1] * i % MOD
        inv_fact = [1] * (limit + 1)
        inv_fact[limit] = pow(fact[limit], MOD-2, MOD)
