def test_bruteforce_small(run, x):
    import sys
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    if n > 8:
        return
    roots = [i for i in range(n) if c[i] == n]
    expected = 'NO'
    if roots:
        for root in roots:
            nodes_order = [i for i in range(n) if i != root]
            parent = [-1]*n
            parent[root] = root
            def backtrack(idx):
                if idx == len(nodes_order):
                    children = [[] for _ in range(n)]
                    for i in range(n):
                        if i != root:
                            children[parent[i]].append(i)
                    for i in range(n):
                        if children[i] and len(children[i]) < 2:
                            return False
                    visited = [False]*n
                    def dfs(v):
                        visited[v] = True
                        sz = 1
                        for u in children[v]:
                            sz += dfs(u)
                        if sz != c[v]:
                            raise ValueError
                        return sz
                    try:
                        dfs(root)
                    except ValueError:
                        return False
                    if not all(visited):
                        return False
                    return True
                node = nodes_order[idx]
                for p in range(n):
                    if p == node:
                        continue
                    if c[p] > c[node]:
                        parent[node] = p
                        if backtrack(idx+1):
                            return True
                        parent[node] = -1
                return False
            if backtrack(0):
                expected = 'YES'
                break
    output = run(x).strip()
    assert output == expected, f'Brute-force mismatch: expected {expected}, got {output}'


