def test_brute_force_oracle(run, x):
    def has_pal_subseq(arr):
        n = len(arr)
        for mask in range(1 << n):
            if bin(mask).count('1') >= 3:
                subseq = [arr[i] for i in range(n) if (mask >> i) & 1]
                if subseq == subseq[::-1]:
                    return True
        return False
    out_lines = run(x).strip().splitlines()
    lines = x.strip().splitlines()
    t = int(lines[0].strip())
    idx = 1
    for i in range(t):
        n = int(lines[idx].strip())
        arr = list(map(int, lines[idx+1].split()))
        idx += 2
        correct = 'YES' if has_pal_subseq(arr) else 'NO'
        out_line = out_lines[i].strip() if i < len(out_lines) else ''
        assert out_line == correct, f'Test case {i+1}: expected {correct}, got {out_line}'


