    if not lines:
        return
    t = int(lines[0].strip())
    arrays = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx].strip())
        idx += 1
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        arrays.append(a)
    output = run(x).strip().splitlines()
    for a, out in zip(arrays, output):
        if out.strip() == 'NO':
            first = {}
            found = False
            for i, val in enumerate(a):
                if val in first and i - first[val] >= 2:
                    found = True
                    break
                first[val] = i
            if found:
                assert False, 'Output NO but pair with gap >=2 exists'

