def test_large_n_pair_beyond_50_implies_yes(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    arrays = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx].strip())
        idx += 1
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        arrays.append(a)
    output = run(x).strip().splitlines()
    for a, out in zip(arrays, output):
        n = len(a)
        if n > 50:
            found = False
            for i in range(n):
                for k in range(i+2, n):
                    if a[i] == a[k] and (i >= 50 or k >= 50):
                        found = True
                        break
                if found:
                    break
            if found and out.strip() != 'YES':
                assert False, f'Pair beyond 50 exists, should output YES, got {out}'

def test_three_occurrences_implies_yes(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    arrays = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx].strip())
        idx += 1
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        arrays.append(a)
    output = run(x).strip().splitlines()
    for a, out in zip(arrays, output):
        from collections import Counter
        cnt = Counter(a)
        if max(cnt.values()) >= 3:
            if out.strip() != 'YES':
                assert False, f'Value appears at least 3 times, should output YES, got {out}'

