def test_all_distinct_possible(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if len(set(s)) == n:
        total = 1 << n  # 2^n
        if k <= total:
            out = run(x).strip()
            assert out != "-1", f"For distinct string, k={k} <= 2^{n}={total}, but output -1"

def test_all_distinct_impossible(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if len(set(s)) == n:
        total = 1 << n
        if k > total:
            out = run(x).strip()
            assert out == "-1", f"For distinct string, k={k} > 2^{n}={total}, but output not -1"

def test_single_char(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if len(set(s)) == 1:
        total = n + 1
        if k > total:
            out = run(x).strip()
            assert out == "-1", f"Single char string, k={k} > n+1={total}, but output not -1"
        else:
            expected_cost = k * (k - 1) // 2
            out = run(x).strip()
            assert out == str(expected_cost), f"Single char string, expected {expected_cost}, got {out}"

def test_small_n_exact(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if n > 12:
        return
    from itertools import combinations
    distinct = set()
    length_counts = {}
    for mask in range(1 << n):
        subseq = ''.join(s[i] for i in range(n) if (mask >> i) & 1)
        distinct.add(subseq)
    for sub in distinct:
        L = len(sub)
        length_counts[L] = length_counts.get(L, 0) + 1
    remaining = k
    cost = 0
    for L in sorted(length_counts.keys(), reverse=True):
        cnt = length_counts[L]
        take = min(remaining, cnt)
        cost += take * (n - L)
        remaining -= take
        if remaining == 0:
            break
    expected = -1 if remaining > 0 else cost
    out = run(x).strip()
    if expected == -1:
        assert out == "-1", f"Expected -1, got {out}"
    else:
        assert out == str(expected), f"Expected {expected}, got {out}"

