def test_brute_force_small(run, x):
    import itertools
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n > 8:
        return
    arr = list(map(int, lines[1].split()))
    area = {}
    indices = list(range(n))
    for comb in itertools.combinations(indices, 4):
        mask = 0
        for i in comb:
            mask |= 1 << i
        lengths = [arr[i] for i in comb]
        best_area = None
        for red in range(16):
            reduced = []
            for idx in range(4):
                l = lengths[idx]
                if (red >> idx) & 1:
                    reduced.append(l - 1)
                else:
                    reduced.append(l)
            reduced.sort()
            if reduced[0] == reduced[1] and reduced[2] == reduced[3]:
                cur_area = reduced[0] * reduced[2]
                if best_area is None or cur_area > best_area:
                    best_area = cur_area
        if best_area is not None:
            area[mask] = best_area
