def test_oracle(run, x):
    n = int(x.strip())
    hex_str = hex(n)[2:]
    holes = {'0':1, '1':0, '2':0, '3':0, '4':1, '5':0, '6':1, '7':0, '8':2, '9':1, 'a':1, 'b':2, 'c':0, 'd':1, 'e':0, 'f':0}
    expected = sum(holes[ch] for ch in hex_str)
    output = run(x).strip()
    assert output == str(expected)

def test_non_negative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_integer(run, x):
    output = run(x).strip()
    int(output)

def test_bound_per_digits(run, x):
    n = int(x.strip())
    hex_len = len(hex(n)[2:])
    max_holes = 2 * hex_len
    output = int(run(x).strip())
    assert output <= max_holes

def test_zero(run, x):
    n = int(x.strip())
    output = run(x).strip()
