def test_power_of_16(run, x):
    n = int(x.strip())
    output = int(run(x).strip())
    if n > 0:
        temp = n
        exponent = 0
        while temp % 16 == 0:
            temp //= 16
            exponent += 1
        if temp == 1:
            assert output == exponent

