def test_exact_oracle(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        best = 1
        i = 1
        while i * i <= n:
            if n % i == 0:
                if i <= k:
                    best = max(best, i)
                if n // i <= k:
                    best = max(best, n // i)
            i += 1
        expected = n // best
        assert p == expected, f"Expected {expected}, got {p}"

def test_output_positive(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for p in outputs:
        assert p > 0

def test_output_divides_n(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        assert n % p == 0, f"Output {p} does not divide n={n}"

def test_package_size_range(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        i = n // p
        assert i * p == n
        assert 1 <= i <= k, f"Package size {i} not in [1, k={k}]"

def test_lower_bound(run, x):
    lines = x.strip().split()
    if not lines:
