def test_special_k_ge_n(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        if k >= n:
            assert p == 1, f"When k>=n, expected 1, got {p}"

def test_special_prime(run, x):
    def is_prime(num):
        if num < 2:
            return False
        if num % 2 == 0:
            return num == 2
        if num % 3 == 0:
            return num == 3
        i = 5
        w = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        if is_prime(n) and k < n:
            assert p == n, f"For prime n={n} and k<n, expected {n}, got {p}"

def test_small_n_bruteforce(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        if n <= 1000000:
            limit = min(k, n)
            best = 1
            for i in range(limit, 0, -1):
                if n % i == 0:
                    best = i
                    break
            expected = n // best
            assert p == expected, f"For small n, expected {expected}, got {p}"

def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    for line in lines:
        stripped = line.strip()
        assert stripped.isdigit(), f"Output line not all digits: {line}"
        assert len(stripped) > 0

def test_output_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output is not an integer"


def test_output_range(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    out = run(x).strip()
    val = int(out)
    assert val == -1 or (0 <= val <= K), f"Output {val} out of range"


def test_neg1_implies_impossible(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    out = run(x).strip()
    val = int(out)
    if val == -1:
        total = sum(A)
        needed = M * N
        assert total + K < needed, f"Output is -1 but total {total} + K {K} >= {needed}"


def test_nonneg_implies_sufficient(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    out = run(x).strip()
    val = int(out)
    if val != -1:
        total = sum(A)
        needed = M * N
        assert total + val >= needed, f"Output {val} insufficient: total {total} + {val} < {needed}"


def test_minimality(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    out = run(x).strip()
    val = int(out)
    if val != -1 and val > 0:
        total = sum(A)
        needed = M * N
        assert total + (val - 1) < needed, f"Output {val} not minimal: total {total} + {val-1} >= {needed}"


def test_if_sum_ge_target_then_zero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    total = sum(A)
    needed = M * N
    if total >= needed:
        out = run(x).strip()
        val = int(out)
        assert val == 0, f"Sum already {total} >= {needed} but output is {val}"


def test_exact_calculation(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    total = sum(A)
    needed = M * N - total
    if needed <= 0:
        correct = 0
    elif needed <= K:
        correct = needed
    else:
        correct = -1
    out = run(x).strip()
    val = int(out)
    assert val == correct, f"Output {val} expected {correct}"


def test_output_ge_neg1(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= -1, f"Output {val} less than -1"


def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped.lstrip('-').isdigit(), f"Output '{out}' not an integer"


def test_average_condition(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    N, K, M = map(int, tokens[:3])
    A = list(map(int, tokens[3:]))
    if len(A) != N - 1:
        return
    out = run(x).strip()
    val = int(out)
    total = sum(A)
    needed = M * N
    if val != -1:
        assert total + val >= needed, f"Average condition failed: {total}+{val} < {needed}"
    else:
        assert total + K < needed, f"Output -1 but total {total}+K {K} >= {needed}"

