def test_output_positive(run, x):
    out = run(x)
    n = int(out.strip())
    assert n >= 1, "Years must be at least 1"

def test_output_upper_bound(run, x):
    out = run(x)
    n = int(out.strip())
    assert n <= 5000, "Years must not exceed 5000"

def test_balance_ge_X(run, x):
    X = int(x.strip())
    out = run(x)
    n = int(out.strip())
    deposit = 100
    for _ in range(n):
        deposit += deposit // 100
    assert deposit >= X, f"Balance after {n} years is {deposit}, less than X={X}"

def test_balance_lt_X_previous_year(run, x):
    X = int(x.strip())
    out = run(x)
    n = int(out.strip())
    if n > 0:
        deposit = 100
        for _ in range(n-1):
            deposit += deposit // 100
        assert deposit < X, f"Balance after {n-1} years is {deposit}, already >= X={X}"

def test_lower_bound_log(run, x):
    import math
    X = int(x.strip())
    out = run(x)
    n = int(out.strip())
    if X <= 100:
        return
    ratio = math.log(X/100) / math.log(1.01)
