def test_X_103(run, x):
    if x.strip() == "103":
        assert run(x).strip() == "3"

def test_X_max(run, x):
    if x.strip() == "1000000000000000000":
        X = 10**18
        deposit = 100
        years = 0
        while deposit < X:
            years += 1
            deposit += deposit // 100
        expected = years
        out = run(x)
        assert int(out.strip()) == expected, f"For X=10^18, expected {expected}"

def test_exact(run, x):
    X = int(x.strip())
    deposit = 100
    years = 0
