def test_format(run, x):
    out = run(x)
    assert out in {"Yes\n", "No\n"}

def test_stripped(run, x):
    out = run(x).strip()
    assert out in {"Yes", "No"}

def test_le_implies_yes(run, x):
    D, T, S = map(int, x.split())
    if D <= T * S:
        out = run(x).strip()
        assert out == "Yes"

def test_gt_implies_no(run, x):
    D, T, S = map(int, x.split())
    if D > T * S:
        out = run(x).strip()
        assert out == "No"

def test_yes_implies_le(run, x):
    D, T, S = map(int, x.split())
    out = run(x).strip()
    if out == "Yes":
        assert D <= T * S

def test_no_implies_gt(run, x):
    D, T, S = map(int, x.split())
    out = run(x).strip()
    if out == "No":
        assert D > T * S

def test_boundary_exact(run, x):
    D, T, S = map(int, x.split())
    if D == T * S:
        out = run(x).strip()
        assert out == "Yes"

def test_boundary_one_more(run, x):
    D, T, S = map(int, x.split())
    if D == T * S + 1:
        out = run(x).strip()
        assert out == "No"

def test_correct_by_ceil(run, x):
    D, T, S = map(int, x.split())
    need = (D + S - 1) // S
    expected = "Yes" if need <= T else "No"
    out = run(x).strip()
    assert out == expected

def test_s_ge_d_implies_yes(run, x):
    D, T, S = map(int, x.split())
    if S >= D:
        out = run(x).strip()
        assert out == "Yes"

