def test_output_format(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, 'Output not an integer'
    assert 0 <= val <= 2018, f'Output {val} not in [0,2018]'

def test_zero_when_L_is_zero(run, x):
    L, R = map(int, x.strip().split())
    if L == 0:
        out = run(x).strip()
        assert out == '0', f'When L=0, expected 0 got {out}'

def test_zero_when_multiple_of_2019_exists(run, x):
    L, R = map(int, x.strip().split())
    first_multiple = ((L + 2018) // 2019) * 2019
    if first_multiple <= R:
        out = run(x).strip()
        assert out == '0', f'Multiple of 2019 present, expected 0 got {out}'

def test_zero_when_range_length_ge_2019(run, x):
    L, R = map(int, x.strip().split())
    if R - L + 1 >= 2019:
        out = run(x).strip()
        assert out == '0', f'Range length >=2019, expected 0 got {out}'

def test_small_range_bruteforce_oracle(run, x):
    L, R = map(int, x.strip().split())
    size = R - L + 1
    if size <= 2000:
        ans = 2019
        for i in range(L, R+1):
            for j in range(i+1, R+1):
                val = (i * j) % 2019
                if val < ans:
                    ans = val
        out = run(x).strip()
        assert int(out) == ans, f'For small range, expected {ans} got {out}'

def test_achievable(run, x):
    L, R = map(int, x.strip().split())
    size = R - L + 1
    if size <= 2000:
        out = run(x).strip()
        v = int(out)
        achievable = False
        for i in range(L, R+1):
            for j in range(i+1, R+1):
                if (i * j) % 2019 == v:
                    achievable = True
                    break
            if achievable:
                break
        assert achievable, f'Output {v} not achievable by any pair in range'

def test_specific_input_0_2018(run, x):
    if x == '0 2018\n':
        out = run(x).strip()
        assert out == '0', f"For input '0 2018', expected 0 got {out}"

def test_specific_input_2019_2020(run, x):
    if x == '2019 2020\n':
        out = run(x).strip()
        assert out == '0', f"For input '2019 2020', expected 0 got {out}"

def test_specific_input_2020_2021(run, x):
    if x == '2020 2021\n':
        out = run(x).strip()
        assert out == '2', f"For input '2020 2021', expected 2 got {out}"

def test_specific_input_1_2019(run, x):
    if x == '1 2019\n':
        out = run(x).strip()
        assert out == '0', f"For input '1 2019', expected 0 got {out}"

