tests_src:
def test_output_equals_range(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    ans = int(run(x).strip())
    assert ans == max(A) - min(A)

def test_output_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_output_format_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_not_all_equal_implies_positive(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    ans = int(run(x).strip())
    if len(set(A)) > 1:
        assert ans > 0

def test_all_equal_implies_zero(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    ans = int(run(x).strip())
    if len(set(A)) == 1:
        assert ans == 0

def test_lower_bound_range(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    ans = int(run(x).strip())
    assert ans >= max(A) - min(A)

def test_upper_bound_range(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    ans = int(run(x).strip())
    assert ans <= max(A) - min(A)

def test_exists_pair_with_difference(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    N = len(A)
    ans = int(run(x).strip())
    found = False
    for i in range(N):
        for j in range(i+1, N):
            if abs(A[i] - A[j]) == ans:
                found = True
                break
        if found:
            break
    assert found

def test_all_pairs_at_most(run, x):
    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    N = len(A)
    ans = int(run(x).strip())
    for i in range(N):
        for j in range(i+1, N):
            assert abs(A[i] - A[j]) <= ans

def test_global_upper_bound(run, x):
    ans = int(run(x).strip())
    assert ans <= 10**9 - 1

