def test_enumeration(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])
    a = list(map(int, lines[1].split()))
    offers = []
    for i in range(m):
        parts = lines[2 + i].split()
        offers.append((int(parts[0]), int(parts[1]), int(parts[2])))
    INF = 10**30
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = cost[j][i] = a[i] + a[j]
    for x, y, w in offers:
        i, j = x - 1, y - 1
        if w < cost[i][j]:
            cost[i][j] = cost[j][i] = w
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j, cost[i][j]))
    import itertools
    min_cost = None
    for combo in itertools.combinations(edges, n - 1):
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                u = parent[u]
            return u
        def union(u, v):
            ru, rv = find(u), find(v)
            if ru != rv:
                parent[rv] = ru
                return True
            return False
        total = 0
        connected = True
        for u, v, w in combo:
            if not union(u, v):
                connected = False
                break
            total += w
        if connected:
            root = find(0)
            for i in range(1, n):
                if find(i) != root:
                    connected = False
                    break
        if connected:
            if min_cost is None or total < min_cost:
                min_cost = total
    if n == 1:
        min_cost = 0
    ans = int(run(x).strip())
    assert ans == min_cost, f"Enumeration expected {min_cost}, got {ans}"

