def test_output_is_integer(run, x):
    out = run(x)
    int(out.strip())

def test_output_positive(run, x):
    m = int(run(x).strip())
    assert m > 0

def test_output_at_least_2(run, x):
    m = int(run(x).strip())
    assert m >= 2

def test_output_not_too_large(run, x):
    m = int(run(x).strip())
    assert m <= 1000000

def test_repetition_at_m(run, x):
    s = int(x.strip())
    m = int(run(x).strip())
    seq = []
    a = s
    for i in range(1, m+1):
        if i > 1:
            if a % 2 == 0:
                a = a // 2
            else:
                a = 3 * a + 1
        seq.append(a)
    assert seq[-1] in seq[:-1]

def test_no_earlier_repetition(run, x):
    s = int(x.strip())
    m = int(run(x).strip())
    if m <= 2:
        return
    seen = set()
    a = s
    for i in range(1, m):
        if i > 1:
            if a % 2 == 0:
                a = a // 2
            else:
                a = 3 * a + 1
        assert a not in seen
        seen.add(a)

def test_correct_answer(run, x):
    s = int(x.strip())
    seen = {}
    a = s
    i = 1
    while True:
        if a in seen:
            m_correct = i
            break
        seen[a] = i
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        i += 1
    m = int(run(x).strip())
    assert m == m_correct

def test_examples(run, x):
    m = int(run(x).strip())
    s = int(x.strip())
    if s == 1:
        assert m == 4
    elif s == 2:
        assert m == 4
    elif s == 8:
        assert m == 5

def test_precomputed_correct(run, x):
    m = int(run(x).strip())
    s = int(x.strip())
    precomputed = {15:19,30:20,60:21,1:4,2:4,8:5,100:27,4:4,5:7,16:6,10:8,3:9,6:10,7:18,12:11,20:9,40:10,23:17,46:18,92:19,80:11,64:8,32:7,24:12,48:13,96:14,9:21,18:22,36:23,72:24}
    if s in precomputed:
        assert m == precomputed[s]

def test_distinct_count(run, x):
    s = int(x.strip())
    m = int(run(x).strip())
    seq = []
    a = s
    for i in range(1, m+1):
        if i > 1:
            if a % 2 == 0:
                a = a // 2
            else:
                a = 3 * a + 1
        seq.append(a)
    distinct = set(seq)
    assert len(distinct) == m-1

