def test_full_oracle(run, x):
    def is_valid(a):
        n = len(a)
        i = 0
        while i < n:
            if a[i] != 1:
                return False
            j = i
            while j < n and a[j] == j - i + 1:
                j += 1
            if j == i:
                return False
            i = j
        return True
    def correct_sizes(a):
        if not is_valid(a):
            return None
        sizes = []
        n = len(a)
        i = 0
        while i < n:
            j = i
            while j < n and a[j] == j - i + 1:
                j += 1
            sizes.append(j - i)
            i = j
        return sizes
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    expected = correct_sizes(a)
    if expected is None:
        return
    output = run(x)
    out_lines = output.strip().split('\n')
    if len(out_lines) < 2:
        assert False, "too few output lines"
    t = int(out_lines[0].strip())
    out_sizes = list(map(int, out_lines[1].split()))
    assert t == len(expected) and out_sizes == expected

