def test_component(run, x):
    import sys
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].split()
    n, m = map(int, first)
    a = list(map(int, lines[1].split()))
    p = set(map(int, lines[2].split()))
    parent = list(range(n + 1))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx
    for pos in p:
        union(pos, pos + 1)
    from collections import defaultdict
    comp = defaultdict(list)
    for i in range(1, n + 1):
        comp[find(i)].append(i)
    sorted_a = sorted(a)
    possible = True
    for indices in comp.values():
        vals_orig = [a[i-1] for i in indices]
        vals_need = [sorted_a[i-1] for i in indices]
        if sorted(vals_orig) != sorted(vals_need):
            possible = False
            break
    expected = 'YES' if possible else 'NO'
    output = run(x).strip()
    assert output == expected, f'Expected {expected}, got {output}'

def test_small_bruteforce(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].split()
    n, m = map(int, first)
    if n > 8:
        return
    a = list(map(int, lines[1].split()))
    p = set(map(int, lines[2].split()))
    from collections import deque
    start = tuple(a)
    target = tuple(sorted(a))
    if start == target:
        expected = 'YES'
    else:
        visited = {start}
        q = deque([start])
        reachable = False
        while q:
            state = q.popleft()
            if state == target:
                reachable = True
                break
            lst = list(state)
            for pos in p:
                i = pos - 1
                j = i + 1
                if j >= n:
                    continue
                new = list(state)
                new[i], new[j] = new[j], new[i]
                newt = tuple(new)
                if newt not in visited:
                    visited.add(newt)
                    q.append(newt)
        expected = 'YES' if reachable else 'NO'
    output = run(x).strip()
    assert output == expected, f'Bruteforce expected {expected}, got {output}'

