def test_full_oracle(run, x):
    a,b,c = map(int, x.strip().split())
    correct = []
    for s in range(1, 200):
        x_val = b * (s**a) + c
        if 0 < x_val < 10**9:
            if sum(map(int, str(x_val))) == s:
                correct.append(x_val)
    correct.sort()
    out = run(x)
    tokens = out.strip().split()
    if not tokens:
        assert False, "empty output"
    n = int(tokens[0])
    if n == 0:
        assert len(tokens) == 1, "extra tokens"
        assert correct == [], "expected no solutions"
    else:
        assert len(tokens) == n+1, "wrong number of tokens"
        sols = list(map(int, tokens[1:]))
        assert sols == correct, "solutions mismatch"

