def test_reachable_cells_only(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n, m, k = map(int, first[:3])
    grid = [list(line.rstrip()) for line in lines[1:1+n]]
    sx = sy = -1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                sx, sy = i, j
                grid[i][j] = '.'
    out = run(x).strip()
    if out == "IMPOSSIBLE":
        return
    from collections import deque
    reachable = [[False]*m for _ in range(n)]
    dq = deque()
    dq.append((sx, sy))
    reachable[sx][sy] = True
    while dq:
        xc, yc = dq.popleft()
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx, ny = xc+dx, yc+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '*' and not reachable[nx][ny]:
