                dq.append((nx, ny))
    xc, yc = sx, sy
    for c in out:
        if c == 'D': xc += 1
        elif c == 'U': xc -= 1
        elif c == 'R': yc += 1
        elif c == 'L': yc -= 1
        else: assert False
        assert reachable[xc][yc], f"Cell ({xc},{yc}) is not reachable from start"

