def test_exact_efficient(run, x):
    a,b = map(int, x.strip().split())
    def correct(a,b):
        ans = 0
        while a and b:
            if a > b:
                ans += a // b
                a %= b
            else:
                ans += b // a
                b %= a
        return ans
    expected = correct(a,b)
    output = run(x).strip()
    assert output == str(expected)

def test_example_2_1(run, x):
    output = run(x).strip()
    if x.strip() == '2 1':
        assert output == '2'

def test_example_10_7(run, x):
    output = run(x).strip()
    if x.strip() == '10 7':
        assert output == '6'

def test_example_large(run, x):
    output = run(x).strip()
    if x.strip() == '1000000000000 1':
        assert output == '1000000000000'

def test_b_eq_1(run, x):
    a,b = map(int, x.strip().split())
    output = run(x).strip()
    if b == 1:
        assert output == str(a)

def test_multiple(run, x):
    a,b = map(int, x.strip().split())
