def test_small_simulation(run, x):
    a,b = map(int, x.strip().split())
    output = run(x).strip()
    if a + b <= 10000:
        def simulate(a,b):
            count = 0
            while a != b:
                if a > b:
                    a -= b
                else:
                    b -= a
                count += 1
            return count + 1
        expected = simulate(a,b)
        assert int(output) == expected

def test_scaling_invariant(run, x):
    import math
    a,b = map(int, x.strip().split())
    output = run(x).strip()
    g = math.gcd(a,b)
    a1, b1 = a//g, b//g
    if max(a1, b1) <= 10000:
        def simulate(a,b):
            count = 0
            while a != b:
                if a > b:
                    a -= b
                else:
                    b -= a
                count += 1
            return count + 1
        expected_reduced = simulate(a1,b1)
        assert int(output) == expected_reduced

