def test_bfs_oracle(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    from collections import deque
    max_b = [-1] * (m+1)
    for a, b in teleports:
        if a <= m:
            max_b[a] = max(max_b[a], b)
    reachable = [False] * (m+1)
    reachable[0] = True
    q = deque([0])
    while q:
        p = q.popleft()
        if max_b[p] != -1:
            for np in range(p, max_b[p]+1):
                if np <= m and not reachable[np]:
                    reachable[np] = True
                    q.append(np)
    correct = 'YES' if reachable[m] else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

