    for a, b in teleports:
        if a <= k:
            k = max(k, b)
    correct = 'YES' if k == m else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

def test_dfs_on_teleports(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    adj = [[] for _ in range(n)]
    for i in range(n):
        ai, bi = teleports[i]
        for j in range(n):
            aj, _ = teleports[j]
            if ai <= aj <= bi:
                adj[i].append(j)
    start_nodes = [i for i in range(n) if teleports[i][0] == 0]
    visited = [False] * n
    stack = start_nodes[:]
    for i in start_nodes:
        visited[i] = True
    while stack:
        i = stack.pop()
        for j in adj[i]:
            if not visited[j]:
                visited[j] = True
                stack.append(j)
    reachable_m = any(visited[i] and teleports[i][1] == m for i in range(n))
    correct = 'YES' if reachable_m else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

