    try:
        val = int(s)
    except ValueError:
        assert False
    assert val <= 10**6 - 2

def test_lower_bound(run, x):
    out = run(x)
    s = out.strip()
    try:
        val = int(s)
    except ValueError:
        assert False
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    a.sort()
    L = max(min(x-1, 10**6 - x) for x in a)
    assert val >= L

def test_feasibility(run, x):
    out = run(x)
    s = out.strip()
    try:
        T = int(s)
    except ValueError:
        assert False
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    a.sort()
    feasible = False
    for i in range(n+1):
        left = a[i-1] - 1 if i > 0 else 0
        right = 10**6 - a[i] if i < n else 0
        if max(left, right) <= T:
            feasible = True
            break
    assert feasible

def test_matches_examples(run, x):
    if x == "3\n2 3 9\n":
        out = run(x).strip()
        assert out == "8"
    elif x == "2\n2 999995\n":
        out = run(x).strip()
        assert out == "5"

def test_brute_force_small_n(run, x):
    out = run(x)
    s = out.strip()
    try:
        val = int(s)
    except ValueError:
        assert False
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n > 8:
        return
    a = list(map(int, lines[1].split()))
    a.sort()
    best = 10**9
    for mask in range(1 << n):
        you = []
        friend = []
        for i in range(n):
            if mask >> i & 1:
                you.append(a[i])
            else:
                friend.append(a[i])
        time_you = max(you) - 1 if you else 0
        time_friend = 10**6 - min(friend) if friend else 0
        time = max(time_you, time_friend)
        if time < best:
            best = time
    assert val == best

def test_formula_L(run, x):
    out = run(x)
    s = out.strip()
    try:
        val = int(s)
    except ValueError:
        assert False
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    a.sort()
    L = max(min(x-1, 10**6 - x) for x in a)
    assert val == L

def test_output_format(run, x):
    out = run(x)
    s = out.rstrip('\n')
    assert s.isdigit()
    assert out == s or out == s + '\n'

def test_binary_search(run, x):
    out = run(x)
    s = out.strip()
    try:
        val = int(s)
    except ValueError:
        assert False
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    a.sort()
    def feasible(T):
        min_max = 10**9
        for i in range(n+1):
            left = a[i-1] - 1 if i > 0 else 0
            right = 10**6 - a[i] if i < n else 0
            min_max = min(min_max, max(left, right))
        return min_max <= T
    lo, hi = 0, 10**6
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    assert val == lo

