def test_reference(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n, m = map(int, lines[0].split())
    xs = []
    ds = []
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        x_i, d_i = map(int, lines[i].split())
        xs.append(x_i)
        ds.append(d_i)
    S_max_n = n * (n - 1) // 2
    if n % 2 == 0:
        S_min_n = n * n // 4
    else:
        S_min_n = (n // 2) * (n // 2 + 1)
    total = 0
    for x_i, d_i in zip(xs, ds):
        total += n * x_i
        if d_i > 0:
            total += d_i * S_max_n
        else:
            total += d_i * S_min_n
    correct_avg = total / n
    out = run(x)
    try:
        ans = float(out.strip())
    except:
        assert False, 'Output not a float'
    eps = 1e-6
    diff = abs(ans - correct_avg)
    if diff > eps and diff > eps * max(abs(ans), abs(correct_avg)):
        assert False

