def test_brute_force_small(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = list(map(int, lines[1].split()))
    R = list(map(int, lines[2].split()))
    G = 1
    for m in M:
        G = G * m // math.gcd(G, m)
    if G > 10**6:
        return
    count = 0
    for d in range(G):
        ok = False
        for i in range(n):
            if d % M[i] == R[i]:
                ok = True
                break
        if ok:
            count += 1
    expected = count / G
    out = float(run(x).strip())
    assert abs(out - expected) <= 1e-4

