def test_pairwise_coprime_zero_r(run, x):
    import math
    lines = x.strip().split('\n')
    M = list(map(int, lines[1].split()))
    R = list(map(int, lines[2].split()))
    if not all(r == 0 for r in R):
        return
    n = len(M)
    coprime = True
    for i in range(n):
        for j in range(i+1, n):
            if math.gcd(M[i], M[j]) != 1:
                coprime = False
                break
        if not coprime:
            break
    if not coprime:
        return
    prod = 1.0
    for m in M:
        prod *= (1 - 1/m)
    expected = 1 - prod
    out = float(run(x).strip())
    assert abs(out - expected) <= 1e-4

