def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_output_non_negative(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_zero_if_same_company(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    s = lines[1].strip()
    if s[a-1] == s[b-1]:
        out = int(run(x).strip())
        assert out == 0

def test_at_least_one_if_different(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    s = lines[1].strip()
    if s[a-1] != s[b-1]:
        out = int(run(x).strip())
        assert out >= 1

def test_at_most_direct_distance(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    out = int(run(x).strip())
    assert out <= abs(a - b)

def test_at_most_distance_to_same_as_a_from_b(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    s = lines[1].strip()
    company_a = s[a-1]
    min_dist = n
    for i in range(1, n+1):
        if s[i-1] == company_a:
            d = abs(i - b)
            if d < min_dist:
                min_dist = d
    out = int(run(x).strip())
    assert out <= min_dist

def test_at_most_distance_to_same_as_b_from_a(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    s = lines[1].strip()
    company_b = s[b-1]
    min_dist = n
    for i in range(1, n+1):
        if s[i-1] == company_b:
            d = abs(i - a)
            if d < min_dist:
                min_dist = d
    out = int(run(x).strip())
    assert out <= min_dist

def test_exact_minimum(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    s = lines[1].strip()
    if s[a-1] == s[b-1]:
        correct = 0
    else:
        direct = abs(a - b)
        min_dist_a = n
        for i in range(1, n+1):
            if s[i-1] == s[a-1]:
                d = abs(i - b)
                if d < min_dist_a:
                    min_dist_a = d
        min_dist_b = n
        for i in range(1, n+1):
            if s[i-1] == s[b-1]:
                d = abs(i - a)
                if d < min_dist_b:
                    min_dist_b = d
        correct = min(direct, min_dist_a, min_dist_b)
    out = int(run(x).strip())
    assert out == correct

def test_at_most_n_minus_1(run, x):
    lines = x.strip().splitlines()
    n, a, b = map(int, lines[0].split())
    out = int(run(x).strip())
    assert out <= n - 1

def test_output_is_digits_only(run, x):
    out = run(x).strip()
    assert out.isdigit()

