        idx = ord(output) - 65
        lines = x.splitlines()
        lengths = [len(line) - 2 for line in lines]
        great = []
        for i in range(4):
            li = lengths[i]
            others = lengths[:i] + lengths[i+1:]
            if all(li * 2 <= oj for oj in others) or all(li >= 2 * oj for oj in others):
                great.append(i)
