        parts = lines[i].split()
        if len(parts) < 3: continue
        x_i = int(parts[0])-1; sign = parts[1]; y_i = int(parts[2])-1
        constraints.append((x_i, sign, y_i))
    positions = list(range(2*n))
    seq = [0]*(2*n)
    count = 0
    def unimodal(seq):
        L = len(seq)
        for split in range(L+1):
            left = seq[:split]; right = seq[split:]
            if all(left[j] <= left[j+1] for j in range(len(left)-1)) and all(right[j] >= right[j+1] for j in range(len(right)-1)):
                return True
        return False
    def dfs(height, free_pos):
        nonlocal count
        if height > n:
            if not unimodal(seq): return
            for x_i, sign, y_i in constraints:
                a = seq[x_i]; b = seq[y_i]
                if sign == '=':
                    if a != b: return
                elif sign == '<':
                    if not (a < b): return
                elif sign == '>':
                    if not (a > b): return
                elif sign == '<=':
                    if not (a <= b): return
                elif sign == '>=':
                    if not (a >= b): return
            count += 1
            return
        for p1, p2 in itertools.combinations(free_pos, 2):
            seq[p1] = height; seq[p2] = height
            new_free = [p for p in free_pos if p not in (p1, p2)]
            dfs(height+1, new_free)
    dfs(1, positions)
    expected = count
    output = run(x).strip()
    try: ans = int(output)
    except: assert False, "Output not integer"
    assert ans == expected, f"Exhaustive count mismatch: expected {expected}, got {ans}"

