    L0 = -10**18
    U0 = 10**18
    has_lower = False
    has_upper = False
    for i in range(1, n+1):
        if d[i-1] == 1:
            L0 = max(L0, 1900 - S[i])
            has_lower = True
        else:
            U0 = min(U0, 1899 - S[i])
