def test_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    c = []
    d = []
    for i in range(1, n+1):
        parts = lines[i].split()
        c.append(int(parts[0]))
        d.append(int(parts[1]))
    total = sum(c)
    S = [0]*(n+1)
    pref = 0
    for i in range(1, n+1):
        S[i] = pref
        pref += c[i-1]
    points = []
    for i in range(1, n+1):
        if d[i-1] == 1:
            points.append(1900 - S[i])
        else:
