def test_output_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert 1 <= len(lines) <= 2, 'Output must have 1 or 2 lines'
    first = lines[0].strip()
    assert first in ('Infinite', 'Finite'), f'First line must be Infinite or Finite, got {first}'
    if first == 'Finite':
        assert len(lines) == 2, 'Finite output must have second line'
        second = lines[1].strip()
        try:
            int(second)
        except ValueError:
            assert False, 'Second line must be an integer'
    else:
        assert len(lines) == 1, 'Infinite output should have only one line'

def test_examples(run, x):
    if x == '3\n2 1 3\n':
        out = run(x).strip()
        expected = 'Finite\n7'
        assert out == expected, f'For example 1 expected {expected}, got {out}'
    if x == '3\n1 2 3\n':
        out = run(x).strip()
        expected = 'Infinite'
        assert out == expected, f'For example 2 expected {expected}, got {out}'

def test_simulation_oracle(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    def simulate(a):
        n = len(a)
        for i in range(n-1):
            if a[i] != 1 and a[i+1] != 1:
                return ('Infinite',)
        sqrt5 = math.sqrt(5)
        if a[0] == 1:
            cur = ('circle', 0.0, 0.0, 5.0)
        elif a[0] == 2:
            b0 = 10.0
            r_inc = b0 / (1 + sqrt5)
            y_base = -r_inc
            cur = ('triangle', 0.0, y_base, b0)
        else:
            cur = ('square', 0.0, 0.0, 10.0)
        points = []
        for i in range(len(a)-1):
            outer = cur
            inner_type = a[i+1]
            if outer[0] == 'circle':
                x_c, y_c, r = outer[1], outer[2], outer[3]
                if inner_type == 2:
                    b = (8/5) * r
                    y_base = y_c - (3/5) * r
                    inner = ('triangle', x_c, y_base, b)
                    pts = [
                        (x_c - b/2, y_base),
                        (x_c + b/2, y_base),
                        (x_c, y_base + b)
                    ]
                else:
                    s = math.sqrt(2) * r
                    inner = ('square', x_c, y_c, s)
                    hs = s/2
                    pts = [
                        (x_c - hs, y_c - hs),
                        (x_c - hs, y_c + hs),
                        (x_c + hs, y_c - hs),
                        (x_c + hs, y_c + hs)
                    ]
            elif outer[0] == 'triangle':
                x_t, y_base, b = outer[1], outer[2], outer[3]
                r = b / (1 + sqrt5)
                x_c = x_t
                y_c = y_base + r
                inner = ('circle', x_c, y_c, r)
                touch_base = (x_t, y_base)
                left_x = x_t - 2*r/math.sqrt(5)
                right_x = x_t + 2*r/math.sqrt(5)
                touch_y = y_base + r * (1 + 1/math.sqrt(5))
                pts = [touch_base, (left_x, touch_y), (right_x, touch_y)]
            else:
                x_s, y_s, s = outer[1], outer[2], outer[3]
                r = s/2
                inner = ('circle', x_s, y_s, r)
                hs = s/2
                pts = [
                    (x_s - hs, y_s),
                    (x_s + hs, y_s),
                    (x_s, y_s - hs),
                    (x_s, y_s + hs)
                ]
            points.extend(pts)
            cur = inner
        unique = []
        for p in points:
            xp, yp = p
            found = False
            for q in unique:
                if abs(xp - q[0]) < 1e-9 and abs(yp - q[1]) < 1e-9:
                    found = True
                    break
            if not found:
                unique.append(p)
        count = len(unique)
        return ('Finite', count)
    expected = simulate(a)
    out = run(x).strip()
    if expected[0] == 'Infinite':
        assert out == 'Infinite', f'Expected Infinite, got {out}'
    else:
        lines_out = out.splitlines()
        assert len(lines_out) == 2, f'Expected two lines for Finite, got {out}'
        assert lines_out[0].strip() == 'Finite', f'First line should be Finite, got {lines_out[0]}'
        try:
            val = int(lines_out[1].strip())
        except:
            assert False, f'Second line not integer: {lines_out[1]}'
        assert val == expected[1], f'Expected count {expected[1]}, got {val}'

