def test_full_oracle(run, x):
    import math
    def compute_answer(n, a):
        # check validity
        for i in range(n-1):
            if a[i] == a[i+1]:
                return None
        # check infinite pairs
        for i in range(n-1):
            if a[i] + a[i+1] == 5:
                return ("Infinite",)
        # initialize first shape
        if a[0] == 1:
            params = ('circle', 0.0, 0.0, 1.0)
        elif a[0] == 2:
            params = ('triangle', 0.0, 0.0, 1.0)
        else:
            params = ('square', 0.0, 0.0, 1.0)
        points = set()
        for i in range(1, n):
            outer_type = a[i-1]
            inner_type = a[i]
            if outer_type == 1 and inner_type == 2:
                cx, cy, R = params[1], params[2], params[3]
                B = 1.6 * R
                base_y = cy - 0.6 * R
                inner_params = ('triangle', cx, base_y, B)
                pts = [(cx, cy+R), (cx - 0.8*R, base_y), (cx + 0.8*R, base_y)]
            elif outer_type == 1 and inner_type == 3:
                cx, cy, R = params[1], params[2], params[3]
                s = R * math.sqrt(2)
                inner_params = ('square', cx, cy, s)
                pts = [
                    (cx - s/2, cy - s/2),
                    (cx + s/2, cy - s/2),
                    (cx + s/2, cy + s/2),
                    (cx - s/2, cy + s/2)
                ]
            elif outer_type == 2 and inner_type == 1:
                cx, base_y, B = params[1], params[2], params[3]
                sqrt5 = math.sqrt(5)
                r = B * (sqrt5 - 1) / 4
                cy_i = base_y + r
                inner_params = ('circle', cx, cy_i, r)
                pts_base = (cx, base_y)
                dx = (2/5) * (B - r)
                y_left = base_y + 0.2*B + 0.8*r
                pts_left = (cx - dx, y_left)
                pts_right = (cx + dx, y_left)
                pts = [pts_base, pts_left, pts_right]
            elif outer_type == 2 and inner_type == 3:
                return ("Infinite",)
            elif outer_type == 3 and inner_type == 1:
                cx, cy, S = params[1], params[2], params[3]
                r = S / 2
                inner_params = ('circle', cx, cy, r)
                pts = [
                    (cx, cy - S/2),
                    (cx, cy + S/2),
                    (cx - S/2, cy),
                    (cx + S/2, cy)
                ]
            elif outer_type == 3 and inner_type == 2:
                return ("Infinite",)
            else:
                # should not happen
                raise ValueError("Unexpected pair")
            for pt in pts:
                rounded = (round(pt[0], 12), round(pt[1], 12))
                points.add(rounded)
            params = inner_params
        return ("Finite", len(points))
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    valid = all(a[i] != a[i+1] for i in range(n-1))
    if not valid:
        return
    expected = compute_answer(n, a)
    if expected is None:
        return
    out = run(x).strip().splitlines()
    if expected[0] == "Infinite":
        assert out[0].strip() == "Infinite"
    else:
        assert out[0].strip() == "Finite"
        assert len(out) >= 2
        num = int(out[1].strip())
        assert num == expected[1]

