def test_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    assert len(parts) == 2, 'output must be two integers or -1'
    try:
        int(parts[0])
        int(parts[1])
    except ValueError:
        assert False, 'output must be integers'

def test_pocket_valid(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    px, py = int(parts[0]), int(parts[1])
    vals = list(map(int, x.strip().split()))
    n, m = vals[0], vals[1]
    assert (px, py) in [(0,0),(n,0),(0,m),(n,m)], f'output {px} {py} is not a pocket'

def test_minus1_condition(run, x):
    out = run(x).strip()
    if out != '-1':
        return
    import math
    def correct_answer(n,m,x,y,vx,vy):
        if (x==0 or x==n) and (y==0 or y==m):
            return None
        if vx==0:
            if x!=0 and x!=n:
                return -1
            if vy>0:
                return (x,m)
            else:
                return (x,0)
        if vy==0:
            if y!=0 and y!=m:
                return -1
            if vx>0:
                return (n,y)
            else:
                return (0,y)
        if x==0 and vx==-1:
            vx=1
        if x==n and vx==1:
            vx=-1
        if y==0 and vy==-1:
            vy=1
        if y==m and vy==1:
            vy=-1
        A=(-vx*x)%n
        B=(-vy*y)%m
        g=math.gcd(n,m)
        if A%g!=B%g:
            return -1
        n1=n//g
        m1=m//g
        r=A%g
        A1=(A-r)//g
        B1=(B-r)//g
        inv_n1=pow(n1,-1,m1)
        k=(B1-A1)*inv_n1%m1
        t_prime=A1+n1*k
        t=r+g*t_prime
        p=(x+vx*t)//n
        q=(y+vy*t)//m
        px=0 if p%2==0 else n
        py=0 if q%2==0 else m
        return (px,py)
    vals=list(map(int,x.strip().split()))
    n,m,x,y,vx,vy=vals
    ans=correct_answer(n,m,x,y,vx,vy)
    if ans is None:
        return
    assert ans==-1, f'ball should fall into pocket {ans} but output is -1'

