def test_simulation_small(run, x):
    vals=list(map(int,x.strip().split()))
    n,m,x,y,vx,vy=vals
    if n>20 or m>20:
        return
    def simulate(n,m,x,y,vx,vy):
        if x==0 and vx==-1:
            vx=1
        if x==n and vx==1:
            vx=-1
        if y==0 and vy==-1:
            vy=1
        if y==m and vy==1:
            vy=-1
        visited=set()
        while True:
            state=(x,y,vx,vy)
            if state in visited:
                return -1
            visited.add(state)
            if (x==0 or x==n) and (y==0 or y==m):
                return (x,y)
            tx=float('inf')
            ty=float('inf')
            if vx>0:
                tx=n-x
            elif vx<0:
                tx=x
            if vy>0:
                ty=m-y
            elif vy<0:
                ty=y
            dt=min(tx,ty)
            x+=vx*dt
            y+=vy*dt
            if tx==dt:
                vx=-vx
            if ty==dt:
                vy=-vy
    expected=simulate(n,m,x,y,vx,vy)
    out=run(x).strip()
    if expected==-1:
        assert out=='-1', f'simulation says no pocket, output {out}'
    else:
        parts=out.split()
        assert len(parts)==2, 'expected pocket, got wrong format'
        px,py=int(parts[0]),int(parts[1])
        assert (px,py)==expected, f'simulation pocket {expected}, got {px} {py}'

