        out = run(x).strip()
        if y0 == 0:
            cy = 0
        else:
            cy = m
        if vx < 0:
            cx = 0
        else:
            cx = n
        expected = f"{cx} {cy}"
        assert out == expected, f"When vy=0 on side, expected {expected}, got {out}"

def test_small_simulation(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if n > 20 or m > 20:
        return
    x, y = x0, y0
    visited = set()
    while True:
        if (x == 0 or x == n) and (y == 0 or y == m):
            expected = f"{x} {y}"
            break
        state = (x, y, vx, vy)
        if state in visited:
            expected = "-1"
            break
        visited.add(state)
        if vx > 0:
            dx = n - x
        elif vx < 0:
            dx = x
        else:
            dx = None
        if vy > 0:
            dy = m - y
        elif vy < 0:
            dy = y
        else:
            dy = None
        if dx is None:
            t = dy
        elif dy is None:
            t = dx
        else:
            t = min(dx, dy)
        if vx != 0:
            x += vx * t
        if vy != 0:
            y += vy * t
        if x == 0 or x == n:
            vx = -vx
        if y == 0 or y == m:
            vy = -vy
    out = run(x).strip()
    assert out == expected, f"Simulation expects {expected}, got {out}"

