        "1 1 2 10\n2\n1 1 3\n2 6 10\n": "-1\n"
    }
    if x in examples:
        out = run(x)
        assert out == examples[x], f"example mismatch: expected {examples[x]!r}, got {out!r}"


def test_output_not_zero(run, x):
    out = run(x)
    s = out.strip()
    try:
        out_int = int(s)
    except:
        assert False, "output not integer"
    if out_int != -1:
        assert out_int != 0, "output is 0 but start != end"


def test_diagonal_path_if_straight(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    first = lines[0].split()
    x0, y0, x1, y1 = map(int, first[:4])
    dx = x1 - x0
    dy = y1 - y0
    if abs(dx) == abs(dy):
        n = int(lines[1])
        total_cells = 0
        segments = []
        for i in range(n):
            r, a, b = map(int, lines[2+i].split())
            segments.append((r, a, b))
            total_cells += b - a + 1
        if total_cells <= 10000:
            allowed = set()
            for r, a, b in segments:
                for col in range(a, b+1):
                    allowed.add((r, col))
            sx = 1 if dx > 0 else -1
            sy = 1 if dy > 0 else -1
            ok = True
            for i in range(0, abs(dx)+1):
                cell = (x0 + sx*i, y0 + sy*i)
                if cell not in allowed:
                    ok = False
                    break
            if ok:
                s = out.strip()
                try:
                    out_int = int(s)
                except:
                    assert False, "output not integer"
                expected = abs(dx)
                assert out_int == expected, f"straight diagonal path should give {expected}, got {out_int}"
